const top_chogath = {
  champion: '초가스',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 빠르게 달려와 침묵을 걸고 (P)\'인내심\'으로 체력을 회복하려 해요. 1~2레벨에는 (Q)\'파열\'을 사용해 가렌의 접근을 늦추거나 공중으로 띄워 이동을 방해하며 웨이브를 받아내세요. 가렌이 (Q)\'결정타\'를 쓰기 전에는 무리하게 붙지 말고 거리 조절에 신경 써야 해요.', lv3: '가렌이 (E)\'심판\'을 돌며 달려들 때 (Q)\'파열\'로 띄워 움직임을 끊고, (W)\'용기\'로 보호막을 얻은 동안에는 억지로 딜교환을 하지 마세요. (Q)\'결정타\'를 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵시킨 뒤 (E)\'날카로운 가시\'를 켠 평타로 피해를 입히세요. 이미 켜진 (Q)\'결정타\' 평타는 침묵으로 끊을 수 없으니 거리를 유지하세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 잃은 체력이 많을수록 강력하니 체력이 낮은 상태에서 가렌과 맞붙는 것은 위험해요. 가렌의 체력이 낮아지면 (R)\'포식\'을 사용하여 확실하게 처치하고 성장을 도모하세요. 가렌이 (E)\'심판\'으로 방어력을 깎기 전에 정글러와 함께 압박하여 라인 주도권을 가져오는 것이 좋아요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 마법 피해를 입히는 것이 효율적이에요. 신발은 가렌의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 효과로 가렌의 (P)\'인내심\' 회복을 억제하면 전투를 더 편하게 이끌 수 있어요.' },
    '갱플랭크': { lv1: '(Q)\'혀어어어업상\'은 대상을 직접 지정해 쏘므로 미니언 뒤에 숨어도 피할 수 없으니 체력 관리에 신경 쓰세요. (Q)\'파열\'을 이용해 거리 조절을 하며 갱플랭크가 다가올 때 둔화를 주어 접근을 막으세요. 근접 평타는 몇 초에 한 번 (P)\'불의 심판\'으로 불을 붙이니 너무 오래 붙어 있지 말고 짧게 치고 빠지세요.', lv3: '(Q)\'파열\'로 적을 띄운 뒤 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 (W)\'괴혈병 치료\'를 쓰기 전에 빠르게 피해를 넣으세요. (E)\'날카로운 가시\'가 켜진 상태에서 평타를 섞어 둔화를 유지하며 추격하세요. 갱플랭크가 (E)\'화약통\'을 설치하면 그 근처에서 싸우지 말고 통을 빠르게 제거해 폭발 피해와 둔화를 방지하세요.', lv6: '(R)\'포탄 세례\'의 둔화 장판 위에서는 (R)\'포식\' 사거리를 잡기 어려우니 장판 밖으로 먼저 벗어나세요. (W)\'괴혈병 치료\'가 빠진 것을 확인하고 (Q)\'파열\'로 띄운 뒤 (R)\'포식\'으로 마무리하여 체력을 성장시키세요. 정글러가 올 때 (W)\'흉포한 울부짖음\'으로 상대 스킬 사용을 막으면 더 쉽게 적을 잡을 수 있어요.', item: '판금 장화를 신어 갱플랭크의 기본 공격 피해를 줄이세요. 강철심장을 첫 코어로 올려 최대 체력을 빠르게 높이고 (R)\'포식\'과 함께 성장 효율을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'괴혈병 치료\'의 체력 회복 효과를 감소시켜 (R)\'포식\'으로 마무리할 확률을 높이세요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 회복하니 초반 소모전에 주의해야 해요. (Q)\'파열\'을 맞춰서 그라가스의 움직임을 둔화시키고 (E)\'날카로운 가시\'를 섞어 딜교환을 시도하세요. 술통이 터지는 위치를 미리 보고 둔화에 걸리지 않게 거리 조절을 잘해야 해요.', lv3: '그라가스가 (W)\'취중 분노\'를 사용하면 받는 피해가 줄어드니 그 스킬이 끝난 뒤에 딜교를 시작하세요. (E)\'몸통 박치기\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 (Q)\'파열\'을 준비하며 거리를 유지하세요. (W)\'흉포한 울부짖음\'으로 그라가스의 스킬 사용을 막으며 딜교를 이어나가세요.', lv6: '그라가스의 (R)\'술통 폭발\'은 적을 멀리 밀어내니 (R)\'포식\'을 쓰기 전에 밀려나지 않도록 주의하세요. (R)\'포식\'으로 마무리할 때 그라가스가 (E)\'몸통 박치기\'로 도망가지 못하도록 (W)\'흉포한 울부짖음\'으로 먼저 침묵을 거는 것이 중요해요. 정글러와 함께 싸울 때는 (Q)\'파열\'로 그라가스를 띄워 연계를 도와주세요.', item: '마법 피해를 줄이기 위해 헤르메스의 발걸음을 가요. 주문력과 체력을 모두 챙길 수 있는 균열 생성기를 첫 코어로 올려요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'을 통한 회복을 억제하며 (R)\'포식\'으로 적을 마무리하기 좋아요.' },
    '그웬': { lv1: '그웬은 (P)\'가위 난도질\'의 체력 비례 피해와 회복 때문에 1~2레벨에 평타 교환을 길게 하면 힘들어요. (Q)\'파열\'을 사용해 적절한 거리를 유지하며 견제하고 그웬이 (Q)\'싹둑싹둑!\'의 중심부에 고정 피해를 입히지 못하게 움직이세요. (P)\'육식\'으로 체력을 회복하며 버티는 것이 중요해요.', lv3: '(W)\'신성한 안개\'는 대상 지정 스킬만 막으므로 (Q)\'파열\'과 (W)\'흉포한 울부짖음\'은 안개 속에도 그대로 들어가요. 그웬이 (E)\'돌격가위\'로 진입하면 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 연계를 끊고 (E)\'날카로운 가시\' 평타로 피해를 입히세요. (Q)\'싹둑싹둑!\'의 가위질 횟수가 적을 때 짧은 딜교환을 유도하세요.', lv6: '(R)\'포식\'은 대상 지정 스킬이라 그웬이 (W)\'신성한 안개\'를 켜면 안개 속으로 직접 들어가야 사용할 수 있어요. (R)\'바느질\'의 둔화에 걸리면 거리를 벌리기 어려우니 (Q)\'파열\'로 먼저 띄운 뒤 (R)\'포식\'으로 마무리하세요. 라인을 밀어두고 정글러를 부르면 (Q)\'파열\'로 띄워 함께 압박하기 좋아요.', item: '마법 저항력과 체력을 함께 챙길 수 있는 심연의 가면을 추천해요. 신발은 마법 저항력과 강인함으로 그웬의 마법 피해와 둔화를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 그웬의 (P)\'가위 난도질\' 회복량을 줄여야 킬각을 잡기 쉬워요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 둔화를 걸며 원거리에서 견제하려 해요. 부메랑은 적을 맞힌 뒤에도 이어서 날아가고 돌아오니 미니언 뒤에 숨기보다 궤적에서 옆으로 비켜서세요. 나르가 평타를 치러 다가올 때 (Q)\'파열\'을 정확히 맞혀 공중으로 띄우세요.', lv3: '나르가 (E)\'폴짝\'으로 진입하면 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 연계를 끊으세요. 이후 (E)\'날카로운 가시\'가 묻은 평타로 둔화를 걸며 짧게 딜교환을 하세요. (P)\'분노 유전자\'가 쌓여 메가 나르로 변신하면 (W)\'쿵쾅\' 기절 범위 밖으로 빠르게 벗어나는 것이 중요해요.', lv6: '작은 나르의 체력이 낮을 때 (Q)\'파열\'로 띄운 뒤 다가가 (R)\'포식\'으로 마무리하세요. 메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절시키니 벽을 등지고 싸우지 마세요. 정글러가 올 때 (W)\'흉포한 울부짖음\'으로 상대의 (E)\'폴짝\' 사용을 막으며 호응하세요.', item: '판금 장화로 나르의 평타 피해를 줄이세요. 강철심장을 올려 최대 체력을 높이면 생존력이 좋아져요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력을 높이고 순간이동으로 빠르게 합류하세요.' },
    '나서스': { lv1: '나서스가 (Q)\'흡수의 일격\'으로 미니언 막타를 챙기려 할 때 (Q)\'파열\'로 접근을 끊어 흐름을 방해하세요. (Q)\'흡수의 일격\'은 처치할 때마다 강해지니 웨이브를 함께 밀어 넣으며 거리를 조절해 막타를 쉽게 먹지 못하게 하세요. 무리하게 맞붙기보다 (Q)\'파열\'로 견제하며 체력을 챙기세요.', lv3: '나서스가 (W)\'쇠약\'을 사용하면 이동 속도와 공격 속도가 줄어드니 무리하게 들어가기보다 거리를 유지하세요. (W)\'흉포한 울부짖음\'으로 나서스의 스킬 사용을 막으며 (Q)\'파열\'을 맞춰 짧게 딜교환을 하고 빠지세요. (E)\'영혼의 불길\' 장판 위에서는 방어력이 깎이니 조심하며 교전해야 해요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜고 공격 범위가 늘어났을 때는 정면 대결을 피하고 거리를 벌리세요. 체력이 낮은 나서스에게 (R)\'포식\'을 사용하면 방어력을 무시하고 큰 피해를 입혀 처치할 수 있어요. 정글러를 부를 때는 라인을 미리 밀어두어 나서스가 (Q)\'흡수의 일격\' 중첩을 쌓지 못하도록 관리하세요.', item: '리안드리의 고통을 첫 코어로 선택하여 체력이 높은 상대에게 지속 피해를 입히세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 체력 회복 효과를 감소시키며 마무리 피해를 입히세요.' },
    '녹턴': { lv1: '(Q)\'파열\'을 사용하여 상대가 다가오지 못하게 견제하며 첫 웨이브를 받으세요. (P)\'그림자 칼날\'의 기본 공격 피해와 회복이 강력하므로 무리하게 붙기보다는 거리 조절에 집중해요.', lv3: '(Q)\'황혼의 인도자\'에 맞으면 상대가 궤적을 타고 빠르게 붙으려 하니 (Q)\'파열\'로 띄워 흐름을 끊으세요. (E)\'말할 수 없는 공포\'는 연결이 끊기지 않으면 공포에 걸리니 스킬 사거리 밖으로 벗어나고, 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵시키세요. 이후 (E)\'날카로운 가시\'로 짧게 딜교환을 해요.', lv6: '(R)\'피해망상\'으로 시야가 줄어든 동안에는 재사용으로 날아오는 돌격에 대비해 체력을 넉넉히 유지하세요. 체력이 낮아진 상대를 (R)\'포식\'으로 처치해 체력을 키우세요. 시야가 제한되는 상황에서는 정글러의 기습에도 주의해요.', item: '판금 장화와 태양불꽃 방패를 가요. 판금 장화는 기본 공격 피해를 감소시키며 태양불꽃 방패는 체력을 높이고 주변에 지속 피해를 입혀요.', spell: '점멸과 순간이동을 추천해요. 빠르게 합류하고 라인에 복귀하여 성장을 유지하기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩을 쌓아 공격력을 높이므로 근접전이 길어지면 위험해요. (Q)\'파열\'을 사용해 적절한 거리를 유지하며 견제하고, (Q)\'학살\'의 도끼날 끝부분에 맞지 않도록 주의하세요. 무리하게 붙지 말고 짧게 교환한 뒤 빠르게 빠지는 것이 중요해요.', lv3: '(E)\'포획\'은 끌어당기며 공중으로 띄우니 끌려가면 스킬을 쓸 수 없어요. 그러니 다리우스가 (E)\'포획\'을 쓰기 전에 거리를 유지하며 (W)\'흉포한 울부짖음\'을 먼저 맞혀 침묵시키세요. (E)\'날카로운 가시\'를 섞어 공격하며 둔화를 걸고 서서히 거리를 벌리세요.', lv6: '(R)\'녹서스의 단두대\'는 출혈 중첩이 높을 때 매우 강력하니 중첩이 쌓였다면 즉시 물러나세요. (R)\'포식\'으로 마무리 킬각을 잡되, 다리우스가 챔피언을 처치하고 궁극기를 초기화할 수 있으니 체력 관리에 유의하세요. 정글러를 호출해 (Q)\'파열\'로 띄운 뒤 빠르게 점사하세요.', item: '강철심장으로 체력을 크게 높여 고정 피해를 버티세요. 신발은 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 다리우스가 붙었을 때 탈진으로 피해량과 속도를 낮춰 생존하세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 이용해 멀리서 견제하며 주도권을 잡으려 해요. (Q)\'과부하\'는 직선형이므로 미니언 뒤에 서서 피해를 줄이고, 라이즈가 미니언을 먹으러 올 때 (Q)\'파열\'을 맞춰 거리를 좁히세요.', lv3: '라이즈가 (E)\'주문 전이\'로 표식을 남긴 뒤 (W)\'룬 감옥\'을 사용하면 속박될 수 있으니 주의해야 해요. 라이즈가 스킬을 연계하기 전에 (Q)\'파열\'로 공중으로 띄우거나 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 스킬 사용을 막으세요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용하여 차원문을 열면 정글러의 개입이나 다른 라인 지원을 의심해야 해요. 라이즈의 체력이 낮을 때 (R)\'포식\'을 적중시키면 큰 피해를 입히며 킬을 노릴 수 있어요.', item: '마법 피해를 줄이기 위해 헤르메스의 발걸음을 먼저 갖추세요. 첫 코어 아이템으로는 체력을 높여 성장을 돕는 강철심장을 추천해요.', spell: '점멸과 점화를 추천해요. 점멸로 (W)\'룬 감옥\'의 사거리를 벗어나거나 거리를 좁힌 뒤, 점화로 (R)\'포식\' 마무리 피해를 더하세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 근접 거리에서 강하게 압박하니 무리하게 붙지 마세요. (Q)\'파열\'을 이용해 럼블의 접근을 늦추며 체력 관리에 집중하고, (P)\'육식\' 패시브로 체력을 회복하며 버텨야 해요. 럼블이 과열 상태가 되어 스킬을 쓰지 못하는 타이밍을 노려 짧게 공격하세요.', lv3: '럼블이 (W)\'고철 방패\'를 켜기 전에 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 연계를 끊으세요. (E)\'전기 작살\'에 맞으면 마법 저항력이 낮아져 피해가 늘어나니 주의하고, (E)\'날카로운 가시\'가 활성화된 상태에서 빠르게 딜교환을 하세요. (Q)\'파열\'로 럼블을 띄운 뒤 접근해 침묵을 거는 것이 효율적이에요.', lv6: '(R)\'이퀄라이저 미사일\' 장판 위에서는 피해가 크고 이동 속도가 느려지니 즉시 범위를 벗어나세요. 럼블의 체력이 낮아졌을 때 (R)\'포식\'으로 확실하게 마무리하여 최대 체력을 성장시키는 것이 중요해요. 럼블이 (W)\'고철 방패\'를 소모한 뒤에 정글러와 함께 진입하면 훨씬 수월하게 잡을 수 있어요.', item: '헤르메스의 발걸음과 대자연의 힘을 추천해요. 마법 저항력을 높여 (Q)\'화염방사기\'의 피해를 줄이고 강인함으로 둔화 지속시간을 줄여야 해요.', spell: '점멸과 순간이동을 추천해요. 럼블의 강력한 라인 푸시력에 대응하고 빠른 합류로 주도권을 잡으세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 입히며 체력을 회복하기 때문에 1~2레벨에는 정면 승부를 피하세요. (Q)\'파열\'을 미니언이나 레넥톤에게 맞춰 거리를 조절하며 견제하세요. 레넥톤의 분노가 쌓여 (Q)\'양떼 도륙\'의 회복량이 늘어나기 전에 거리를 유지하는 게 중요해요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입하면 (W)\'무자비한 포식자\'를 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵시키세요. (W)\'무자비한 포식자\'의 기절을 맞으면 스킬을 쓸 수 없으니 이 스킬을 쓰도록 내버려 두면 안 돼요. 레넥톤이 돌진을 쓴 뒤 다시 들어오려 할 때 (Q)\'파열\'로 띄워 진입을 끊으세요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력을 얻고 분노를 빠르게 채우면 무리하게 싸우지 말고 라인을 당기세요. 레넥톤의 (R)\'강신\' 지속 시간이 끝나면 (R)\'포식\'으로 체력이 낮은 레넥톤을 마무리하는 것이 좋아요. 정글러가 올 때 (Q)\'파열\'로 레넥톤을 띄워 아군과 함께 대응하세요.', item: '첫 코어로 리안드리의 고통을 가서 지속적인 피해를 입히세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\'에 의한 체력 회복을 줄여서 교환을 잘 하세요.' },
    '렝가': { lv1: '렝가가 수풀에서 (P)\'보이지 않는 포식자\' 효과로 도약하는 것을 경계하며 거리를 조절하세요. (Q)\'파열\'을 적절히 사용하여 상대의 접근을 늦추며 미니언과 함께 라인을 관리해요. (P)\'육식\'을 통해 체력을 유지하며 버티는 것이 중요해요.', lv3: '렝가의 (W)\'전투의 포효\'가 군중 제어를 해제하기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵을 거는 것이 중요해요. (Q)\'파열\'로 적을 공중으로 띄운 뒤 (E)\'날카로운 가시\'로 추가 피해를 입히세요. 상대의 (E)\'올가미 투척\' 사거리에 들어가지 않도록 주의해요.', lv6: '렝가가 (R)\'사냥의 전율\'을 사용하여 위장 상태로 접근하며 방어력을 감소시킬 때를 조심하세요. (R)\'포식\'을 사용하여 체력을 키우며 성장하고 상대의 진입에 맞춰 대응하세요. 정글러의 개입에 대비해 라인 관리도 신경 써야 해요.', item: '판금 장화와 강철심장을 추천해요. 렝가의 기본 공격 피해를 줄이고 체력을 높여서 버티기 위해서예요.', spell: '점멸과 탈진을 선택하세요. 렝가의 돌발적인 진입을 늦추고 피해량을 감소시키기 위해서예요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'와 (P)\'룬 검\'을 활용해 매우 공격적으로 진입해요. (Q)\'파열\'을 리븐의 발밑에 정확히 맞춰 공중으로 띄워 진입 흐름을 끊고 거리 조절을 하세요. 평타 한두 번 이후 (P)\'룬 검\' 추가 피해를 입기 전에 뒤로 빠지는 게 좋아요.', lv3: '리븐이 (Q)\'부러진 날개\'로 진입할 때 (W)\'흉포한 울부짖음\'을 사용해 (W)\'기 폭발\' 연계를 침묵으로 끊어주세요. (E)\'용맹\'의 보호막이 사라진 시점에 (E)\'날카로운 가시\'를 섞은 평타로 피해를 입히는 것이 효율적이에요. (Q)\'파열\'은 리븐의 이동 경로를 예측해 맞히면 이후 딜교환 주도권을 가져오기 편해요.', lv6: '(R)\'추방자의 검\'을 켠 리븐은 공격 사거리가 늘어나니 체력이 낮을 때 원거리 베기 공격을 조심하세요. 리븐의 돌진기가 빠진 순간 (R)\'포식\'으로 강력한 고정 피해를 입혀 마무리하는 각을 보세요. 라인을 당겨 정글의 도움을 받거나, (Q)\'파열\'로 적절히 웨이브를 유지하며 기회를 기다리세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. 판금 장화로 (P)\'룬 검\'이 섞인 평타 피해를 줄이고, 태양불꽃 방패의 방어력과 체력으로 리븐의 폭발적인 피해를 버티세요.', spell: '점멸과 순간이동을 추천해요. 리븐의 (Q)\'부러진 날개\' 진입을 점멸로 피하거나 (R)\'포식\' 각을 잡기 위해 사용하세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'을 미니언 사이로 던져 둔화를 걸며 압박하니 옆으로 위치를 옮기며 피해 주세요. (Q)\'파열\'을 사용하여 리산드라가 다가오기 전에 미리 땅을 파열시켜 거리를 조절하세요. 1~2레벨에는 무리한 근접 교환보다는 체력 관리에 집중해요.', lv3: '리산드라가 (W)\'서릿발\'로 속박을 걸더라도 (W)\'흉포한 울부짖음\'을 사용하여 상대의 스킬 사용을 방해할 수 있어요. 리산드라가 (E)\'얼음갈퀴 길\'을 재사용하여 순간이동하기 전에 (W)\'흉포한 울부짖음\'을 미리 맞히는 것이 중요해요. (Q)\'파열\'을 맞힌 뒤 (E)\'날카로운 가시\'를 활용해 딜교환을 시도하세요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용하여 무적이 되면 잠시 딜을 멈추고 기다려 주세요. 리산드라의 (Q)\'얼음 파편\' 콤보를 견디며 버티다가 체력이 낮아진 타이밍에 (R)\'포식\'으로 킬각을 잡으세요. 상대 정글러의 개입에 대비해 라인을 적절히 관리하며 시야를 확보해요.', item: '마법 저항력을 높여주는 헤르메스의 발걸음과 체력을 쌓아 성장을 돕는 강철심장을 추천해요. 리산드라의 마법 피해를 견디며 몸집을 키우기에 좋아요.', spell: '점멸과 정화를 추천해요. 리산드라의 (W)\'서릿발\' 속박이나 (R)\'얼음 무덤\' 기절을 정화로 빠르게 해제하고 대응할 수 있어요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'을 통해 평타 교환이 강하지만 1~2레벨에는 몸이 약해요. (Q)\'파열\'로 지면을 파열시켜 마스터 이의 접근을 늦추며 거리를 조절하세요. 무리하게 맞대결하기보다 (Q)\'파열\'의 공중 띄우기를 활용해 접근을 방해하며 버텨야 해요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용했다면 그 직후를 노려야 해요. 마스터 이가 착지한 직후 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 딜교환을 끊고 (Q)\'파열\'로 공중으로 띄워 마스터 이가 다시 붙지 못하도록 조절하세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 (Q)\'파열\'의 둔화가 통하지 않으니 주의하세요. 하지만 (Q)\'파열\'의 공중 띄우기는 여전히 유효하므로 이를 이용해 진입을 막고 (R)\'포식\'으로 마무리하세요. 마스터 이가 적 챔피언을 처치해 스킬 쿨타임이 줄어들지 않도록 정글러와 함께 압박하세요.', item: '판금 장화와 가시 갑옷을 선택하세요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 가시 갑옷은 마스터 이에게 고통스러운 상처를 남겨요.', spell: '점멸과 점화를 추천해요. 점화로 적의 체력 회복 효과를 감소시켜 마스터 이를 확실히 처치하세요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 체력을 회복하며 압박해요. 1~2레벨에는 (Q)\'파열\'로 마오카이를 공중으로 띄워 거리 조절을 하고 (E)\'날카로운 가시\'로 피해를 입히세요. 마오카이가 평타로 회복하지 못하도록 적절한 거리를 유지해야 해요.', lv3: '(W)\'뒤틀린 전진\'을 쓰는 동안 마오카이는 대상으로 지정할 수 없지만 (Q)\'파열\'과 (W)\'흉포한 울부짖음\'은 범위 스킬이라 그대로 맞힐 수 있어요. (W)\'뒤틀린 전진\'에 속박되어도 스킬은 사용할 수 있으니 (W)\'흉포한 울부짖음\'으로 대응하세요. (E)\'묘목 던지기\'가 깔린 수풀 근처에서는 교환을 피하세요.', lv6: '마오카이가 (R)\'대자연의 마수\'로 벽을 세우면 옆으로 이동하여 속박을 피하세요. 체력이 낮은 마오카이에게 (R)\'포식\'을 사용하면 고정 피해로 확실하게 처치할 수 있어요. 마오카이가 궁극기를 쓰면 라인을 밀기보다 정글러의 개입에 대비하세요.', item: '마법 피해를 입히는 마오카이를 상대하므로 헤르메스의 발걸음을 추천해요. 첫 코어 아이템으로는 적을 불태우는 리안드리의 고통을 가세요.', spell: '점멸과 순간이동을 추천해요. 마오카이가 라인을 비우고 합류하러 가면 순간이동으로 따라가거나 라인 손해를 줄이세요.' },
    '말자하': { lv1: '말자하는 (P)\'공허 태세\'가 활성화되면 받는 피해가 줄고 군중 제어에 면역이 되지만, 피해를 입거나 군중 제어에 맞으면 잠시 후 사라져요. 그러니 평타로 먼저 피해를 입힌 뒤 (Q)\'파열\'을 노리세요. (Q)\'공허의 부름\' 침묵 투사체가 날아오는 위치를 확인해 피하면서 미니언 막타를 챙기세요.', lv3: '(E)\'재앙의 환상\'과 (W)\'공허의 무리\'가 함께 들어오면 지속 피해가 심하므로 길게 싸우지 말고 빠르게 빠지세요. (P)\'공허 태세\'로 군중 제어에 면역인 동안에는 (Q)\'파열\'이 통하지 않으니 먼저 피해를 입힌 뒤 (Q)\'파열\'과 (W)\'흉포한 울부짖음\'을 쓰세요. 침묵은 (Q)\'공허의 부름\'을 쓰기 전에 맞혀야 스킬을 막을 수 있어요.', lv6: '(R)\'황천의 손아귀\'에 제압당하면 (R)\'포식\'을 사용할 수 없으니, 상대의 궁극기가 빠진 것을 확인하고 진입하세요. (Q)\'파열\'로 거리를 좁힌 뒤 (R)\'포식\'으로 체력이 낮은 말자하를 마무리해 성장을 챙기세요. 제압은 정화로 풀 수 없으므로 정글러가 근처에 있을 때 무리하게 들어가지 않도록 시야를 확보하세요.', item: '케이닉 루컨을 추천해요. 높은 마법 저항력과 마법 보호막으로 말자하의 지속 마법 피해를 버틸 수 있어요. 신발은 (Q)\'공허의 부름\'의 침묵 시간을 줄여 주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 순간이동을 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니, 라인 관리를 통해 손해를 줄이고 빠르게 복귀하는 것이 효율적이에요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 둔화시키며 견제하는데 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (P)\'화강암 방패\'가 활성화된 상태에서 평타를 치면 손해니 방패가 사라진 뒤에 (E)\'날카로운 가시\'를 묻혀 짧게 딜교환하세요. 방패가 재생성되기 전에 계속 압박하며 체력을 깎는 것이 중요해요.', lv3: '(W)\'천둥소리\'를 켠 말파이트가 붙어 평타를 치면 피해가 크니 거리를 유지하며 (Q)\'파열\'로 접근을 늦추세요. 상대가 (E)\'지면 강타\'로 공격 속도를 낮추려 다가오면 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 연계를 끊어주세요. (E)\'날카로운 가시\'의 둔화와 (Q)\'파열\'의 공중 띄우기를 조합해 피해를 누적시키세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 (Q)\'파열\'로도 막을 수 없고 맞으면 공중에 떠서 아무것도 못 해요. 정글러가 근처에 있을 때는 말파이트의 돌진 거리 밖에서 라인을 유지하세요. 말파이트가 궁극기를 헛쳤을 때가 기회이니 (R)\'포식\'으로 체력을 깎아 처치하고 성장을 가속하세요.', item: '마법 피해 비중이 높은 말파이트를 상대하기 위해 마법 저항력과 체력을 주는 심연의 가면을 첫 코어로 가세요. 신발은 마법 저항력과 강인함으로 (Q)\'지진의 파편\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 말파이트의 라인 압박이 강하지 않아 성장을 챙기며 팀 교전에 합류하는 것이 효율적이에요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'을 한 명에게 맞히면 피해가 커지니 미니언 근처에서 거리를 조절하며 받아내세요. (Q)\'파열\'을 사용하여 모데카이저가 접근하는 것을 방해하며 미니언을 챙기는 것이 좋아요. 1~2레벨에는 무리한 교전보다는 성장에 집중하세요.', lv3: '모데카이저의 (E)\'죽음의 손아귀\'가 빠진 것을 확인하고 (Q)\'파열\'을 맞춰 거리를 조절하세요. 모데카이저가 (W)\'불멸\'로 보호막을 생성하기 전에 (W)\'흉포한 울부짖음\'을 사용해 침묵을 거는 것이 효율적이에요. (E)\'날카로운 가시\'를 함께 사용하여 둔화를 거세요.', lv6: '모데카이저가 (R)\'죽음의 세계\'를 사용하면 능력치를 빼앗기고 정글러도 도와줄 수 없으니 궁극기가 있을 때는 체력이 낮은 상태로 싸우지 마세요. (R)\'죽음의 세계\'에 끌려가면 순간이동이나 궁극기로 빠져나갈 수 없고 수은 장식띠로도 풀 수 없으니 상대의 궁극기가 빠질 때까지 거리를 유지하세요. 모데카이저가 (Q)\'말살\'로 연계하기 전에 (Q)\'파열\'로 끊어주는 것이 중요해요.', item: '리안드리의 고통과 헤르메스의 발걸음을 추천해요. 리안드리의 고통은 지속적인 피해를 주기 좋고 헤르메스의 발걸음은 모데카이저의 마법 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화는 모데카이저가 (W)\'불멸\'을 통해 체력을 회복하는 것을 억제해 줘요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'을 던져 현재 체력에 비례한 피해를 입히고 둔화를 걸어요. 뼈톱은 처음 맞는 적에게 적중하니 미니언 뒤에 서서 피하며, (Q)\'파열\'로 거리를 조절하며 견제하세요. (P)\'가고 싶은 데로 간다\'는 처음 적중하는 기절이나 속박 같은 이동 불가 효과에만 저항하고 재사용 대기시간이 있으니 항상 켜져 있다고 보지 마세요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 사용하면 받는 피해를 저장했다가 회복하니 이를 먼저 사용하게 유도하거나 효과가 끝날 때까지 거리를 유지하세요. 문도 박사가 (E)\'둔기에 의한 외상\'을 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞춰 스킬 사용을 막고 (E)\'날카로운 가시\'를 사용하여 짧게 딜교환을 하세요. (Q)\'파열\'을 적중시켜 움직임을 제약하며 안정적으로 피해를 입히는 것이 중요해요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력을 즉시 회복하고 이동 속도가 빨라지니 무리하게 추격하지 마세요. 문도 박사의 회복 수단이 사라진 것을 확인한 뒤 (R)\'포식\'을 사용하여 고정 피해로 마무리하세요. (Q)\'파열\'로 적을 공중으로 띄운 뒤 (R)\'포식\'을 사용하면 체력을 성장시키며 확실하게 처치할 수 있어요.', item: '리안드리의 고통을 첫 코어로 선택해 스킬 공격으로 적을 불태우세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 문도 박사의 체력 회복 효과를 감소시켜야 킬을 낼 수 있어요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 멀리서 견제하니 무작정 다가가지 마세요. 화살은 적을 관통하므로 미니언 뒤에 숨기보다 충전할 때 옆으로 움직여 피하고, 쏜 직후에 (Q)\'파열\'을 맞히며 거리를 좁히세요. 1~2레벨에는 체력을 보존하며 막타를 챙기세요.', lv3: '바루스가 (W)\'역병 화살\' 중첩을 쌓은 뒤 스킬로 터뜨려 체력 비례 피해를 주니 주의하세요. (E)\'퍼붓는 화살\' 장판 위에서는 회복력이 줄어드니 빠르게 벗어나세요. 바루스가 다가온 순간 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 연계를 끊고 (E)\'날카로운 가시\' 평타로 압박하세요.', lv6: '바루스가 (R)\'부패의 사슬\'로 속박시키면 그대로 견제 대상이 되니 정글러와 함께 진입하세요. (Q)\'파열\'로 먼저 띄운 뒤 다가가서 (R)\'포식\'으로 마무리해 체력을 키우세요. 바루스가 궁극기를 빗맞혔을 때가 가장 좋은 공격 기회예요.', item: '판금 장화를 신어 바루스의 기본 공격 피해를 줄이세요. 강철심장을 첫 코어로 선택해 체력을 크게 높이고 기본 체력 재생 능력을 챙기세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가 효과로 원거리인 바루스에게 빠르게 접근할 수 있어요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 최대 체력 비례 고정 피해를 입히므로 정면에서 평타 교환을 오래 하는 것은 위험해요. (Q)\'파열\'을 사용해 베인의 접근을 늦추고 미니언을 빠르게 정리하며 최대한 버티세요. 1~2레벨에는 체력 관리를 하며 경험치를 챙기는 것이 중요해요.', lv3: '베인의 (E)\'선고\'에 맞았을 때 벽에 부딪혀 기절하지 않도록 벽에서 멀리 떨어져서 움직이세요. (Q)\'파열\'로 베인을 띄운 뒤 (W)\'흉포한 울부짖음\'으로 침묵을 걸면 (Q)\'구르기\'로 도망치는 것을 잠시 막을 수 있어요. (E)\'날카로운 가시\'를 묻힌 평타로 둔화를 걸어 거리를 좁히는 구도를 만드세요.', lv6: '(R)\'결전의 시간\'을 사용한 베인은 (Q)\'구르기\'를 쓸 때 투명 상태가 되어 (R)\'포식\'을 사용하기 까다로워져요. 베인이 투명화로 빠져나가기 전에 (Q)\'파열\'로 공중으로 띄운 뒤 빠르게 접근해 (R)\'포식\'으로 마무리하세요. 라인을 당겨서 정글의 도움을 받거나 베인이 무리하게 들어오는 순간을 노리세요.', item: '강철심장을 첫 코어로 가서 최대 체력을 높여 체력 기반 피해를 버티세요. 신발은 베인의 기본 공격 피해를 줄여 주는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 베인의 견제로 인해 라인 유지력이 부족할 수 있으므로 순간이동으로 빠르게 복귀하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'를 사용해 빠르게 접근한 뒤 기절을 시키며 공격해요. 1~2레벨에는 볼리베어가 달려들지 못하도록 (Q)\'파열\'을 적절히 사용해 접근을 차단하거나 둔화시키세요. 볼리베어의 (P)\'무자비한 폭풍\' 중첩이 쌓이기 전에 거리를 조절하며 (E)\'날카로운 가시\'로 압박하세요.', lv3: '볼리베어의 (W)\'광란의 상처\'는 표식을 남기고 다시 사용하면 체력을 회복하니 표식이 남았을 때는 거리를 벌려야 해요. 볼리베어가 (E)\'천공 분열\'을 사용할 때 그 범위 밖에서 대기하며 (Q)\'파열\'로 볼리베어의 진입을 끊어주세요. 볼리베어의 (Q)\'번개 강타\'가 빠진 시점에 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 딜교환을 시도하세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 다이브를 올 수 있으니 체력이 낮을 때는 주의하세요. 볼리베어의 (E)\'천공 분열\'로 보호막을 얻기 전에 (Q)\'파열\'로 공중에 띄워 흐름을 끊는 것이 중요해요. 체력이 낮은 볼리베어를 발견하면 (R)\'포식\'을 사용해 고정 피해로 마무리하고 성장을 도모하세요.', item: '리안드리의 고통을 첫 코어로 선택하고 판금 장화를 신으세요. 볼리베어는 체력이 높은 경우가 많아 리안드리의 고통 지속 피해가 효율적이며 판금 장화는 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 볼리베어의 (W)\'광란의 상처\' 체력 회복을 줄이기 위해 점화를 사용하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제하는데, 이 스킬은 대상 지정이라 미니언 뒤에 숨어도 피할 수 없어요. (Q)\'파열\'을 사용하여 적의 진입을 늦추고 무리하게 붙지 않으며 체력을 보존하세요. (E)\'날카로운 가시\'를 켜고 짧게 평타를 섞어 피해를 입히는 것이 좋아요.', lv3: '(E)\'선혈의 파도\'는 투사체가 유닛에 막히므로 항상 미니언 뒤에 서서 피해를 최소화하세요. 블라디미르가 (W)\'피의 웅덩이\'로 변하면 공격 대상이 되지 않으니 스킬 사용을 멈추고 웅덩이가 끝날 때까지 기다려야 해요. 적이 웅덩이를 쓴 직후 (W)\'흉포한 울부짖음\'으로 침묵시켜 (Q)\'수혈\'을 쓰지 못하게 방해하며 (Q)\'파열\'로 띄우세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니, 블라디미르가 궁극기를 사용하면 즉시 뒤로 빠지세요. 블라디미르의 (W)\'피의 웅덩이\'가 빠진 시점에 (Q)\'파열\'로 띄운 뒤 (R)\'포식\'을 사용해 고정 피해로 마무리하세요. 라인을 적당히 당겨 정글의 도움을 받으며 (R)\'포식\' 스택을 쌓는 것이 중요해요.', item: '헤르메스의 발걸음과 심연의 가면을 추천해요. 마법 저항력을 얻어 (Q)\'수혈\' 피해를 줄이고 주변 적이 입는 마법 피해를 늘려 (Q)\'파열\'의 효율을 높일 수 있어요.', spell: '점멸과 점화를 추천해요. 블라디미르는 (Q)\'수혈\'로 계속 체력을 회복하므로 점화로 회복량을 줄여야 처치할 수 있어요.' },
    '뽀삐': { lv1: '뽀삐는 (Q)\'망치 강타\'로 둔화를 걸며 압박하니 폭발 지점을 조심하세요. (Q)\'파열\'로 뽀삐의 움직임을 제어하며 미니언을 챙기세요. 뽀삐가 (P)\'강철의 외교관\'으로 보호막을 얻기 전에 짧게 교환하는 것이 좋아요.', lv3: '뽀삐의 (E)\'용감한 돌진\'에 밀려 벽에 부딪히면 기절하니 벽을 등지지 말고, 돌진해 오면 (Q)\'파열\'로 띄워 대응하세요. (W)\'흉포한 울부짖음\'으로 뽀삐가 스킬을 쓰기 전에 침묵을 걸어 딜교를 진행하세요. (W)\'굳건한 태세\'는 돌진하는 적을 막는 스킬이라 돌진기가 없는 초가스의 교환을 막지 못하니 신경 쓰지 말고 짧게 교환하세요.', lv6: '(R)\'포식\'을 사용하면 체력이 낮은 뽀삐를 처치하고 성장할 수 있어요. 뽀삐의 (R)\'수호자의 심판\'은 충전을 마치면 멀리 날려버리니 충전이 시작되면 옆으로 벗어나세요. 라인을 밀어 넣으며 정글러의 개입에 대비해 체력 관리를 철저히 해요.', item: '첫 코어로 균열 생성기를 선택해 전투 지속력을 높이세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐의 체력을 낮춰 (R)\'포식\'으로 마무리할 수 있게 만드세요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나며 뒤의 적까지 맞히니 미니언 뒤로 피하려 하지 마세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하기 시작하면 범위 밖으로 움직여서 헛치게 만들고 그 틈에 (Q)\'파열\'을 사용해 보세요.', lv3: '사이온의 (W)\'영혼의 용광로\' 보호막이 유지되는 동안에는 딜교환을 피하고 보호막이 사라진 뒤에 공격하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하면 범위 밖으로 빠져 헛치게 만든 뒤 (Q)\'파열\'을 맞히세요. (W)\'흉포한 울부짖음\'을 사용하여 사이온의 스킬 연계를 방해하는 것도 좋아요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'을 사용하며 돌진하면 길목에서 빠르게 비켜서서 피해를 입지 않도록 하세요. 사이온은 처치되어도 (P)\'영광스러운 죽음\'으로 잠시 되살아나 빠르게 공격하니, 쓰러뜨린 뒤에는 바로 거리를 벌리세요. 체력이 낮은 사이온을 (R)\'포식\'으로 처치해 체력을 키우며 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어 아이템으로 선택해 지속적인 피해를 입히세요. 신발은 사이온의 기본 공격 피해량을 줄이기 위해 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 밀어 두는 경향이 있으니 순간이동으로 라인 손해를 방지하는 것이 좋아요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 견제하며 (P)\'페트리사이트 폭발\'이 섞인 평타로 압박해요. 사슬이 교차하는 지점의 폭발 피해를 피하고, 사일러스가 미니언을 잡으러 다가올 때 (Q)\'파열\'로 띄워 피해를 입히세요. 초반에는 무리하게 붙기보다 거리 조절을 하며 체력을 보존하세요.', lv3: '사일러스가 (E)\'도주\'로 돌진한 뒤 (E)\'억압\'으로 사슬을 던지면 맞은 적이 공중으로 띄워지니, 사슬을 던지기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵시키세요. (E)\'날카로운 가시\'가 활성화된 상태에서 평타를 쳐서 이동 속도를 늦추고 딜교환을 하세요. (W)\'국왕시해자\'는 챔피언에게 맞히면 체력을 회복하니 길게 싸우지 말고 짧게 싸우고 빠지세요.', lv6: '사일러스가 (R)\'강탈\'로 뺏어간 (R)\'포식\'에 처치당하지 않도록 체력 관리에 신경 쓰세요. 사일러스의 진입을 (Q)\'파열\'로 끊어낸 뒤, 체력이 낮은 순간에 (R)\'포식\'으로 마무리해 성장하세요. 정글러가 올 때 (W)\'흉포한 울부짖음\'으로 상대의 도주기를 봉쇄해 킬각을 잡으세요.', item: '심연의 가면을 첫 코어로 가서 사일러스의 마법 피해를 견디고 내 마법 피해를 높이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'국왕시해자\'를 통한 사일러스의 체력 회복을 억제하세요.' },
    '세주아니': { lv1: '1~2레벨에는 세주아니의 (Q)\'혹한의 맹습\' 돌진을 조심하며 거리를 유지해요. (Q)\'파열\'을 사용하여 적의 접근을 늦추고 미니언과 함께 체력을 관리해요. 세주아니가 (W)\'혹한의 서릿발\'로 둔화를 걸며 붙지 못하게 조절하는 것이 중요해요.', lv3: '스킬이 모인 뒤에는 세주아니의 (Q)\'혹한의 맹습\'을 먼저 빼도록 유도해요. 상대의 돌진이 빠졌을 때 (Q)\'파열\'과 (E)\'날카로운 가시\'를 활용해 딜교환을 진행해요. 세주아니가 (E)\'만년 서리\'로 기절을 시도하기 전에 (W)\'흉포한 울부짖음\'을 적절히 사용하여 대응해요.', lv6: '(R)\'포식\'을 활용해 체력이 낮은 세주아니를 마무리할 수 있어요. 다만 세주아니의 (R)\'빙하 감옥\'에 맞아 기절하면 스킬을 쓸 수 없으니 주의해야 해요. 라인을 밀어 넣으며 정글러가 개입할 때 (Q)\'파열\'로 적을 띄워 도와주세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 선택해요. 세주아니의 마법 피해를 줄이고 지속적인 피해를 입히기 위해서예요.', spell: '점멸과 점화를 추천해요. 세주아니를 (R)\'포식\'으로 마무리할 때 화력을 높이기 위해서예요.' },
    '세트': { lv1: '세트가 (Q)\'주먹다짐\'으로 이동 속도를 높여 접근할 때는 (Q)\'파열\'을 사용하여 접근을 늦추세요. 세트는 잃은 체력에 비례해 (P)\'투기장의 투지\'로 체력을 회복하므로 길게 싸우기보다 (E)\'날카로운 가시\'로 견제하며 거리를 유지해요.', lv3: '세트의 (E)\'안면 강타\'가 미니언과 나를 동시에 휩쓸어 기절시키지 않도록 위치 선정을 잘하세요. 세트가 (W)\'강펀치\'를 쓰기 전 (W)\'흉포한 울부짖음\'을 맞춰 스킬 사용을 막고 (Q)\'파열\'로 세트의 진입을 방해하며 딜교환을 해요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 내리꽂기 전에 (R)\'포식\'을 사용할 타이밍을 신중히 결정하세요. 세트의 체력이 낮을 때 (R)\'포식\'을 사용하여 큰 피해를 주고 성장을 이어가세요. 세트가 (W)\'강펀치\'를 사용해 보호막을 얻었다면 무리하게 싸우지 말고 라인을 관리해요.', item: '강철심장을 첫 코어로 선택해 체력을 높여 성장을 도모하세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 세트의 (P)\'투기장의 투지\' 회복을 줄이세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 입히며 (P)\'기 보호막\'을 얻으니 무리한 맞딜은 피하세요. 1~2레벨에는 (Q)\'파열\'을 사용하여 쉔이 다가오지 못하게 둔화를 걸며 거리를 유지하세요. 쉔의 기의 검이 지나가는 경로를 피해 평타 견제를 받아내야 해요.', lv3: '쉔이 (W)\'의지의 결계\'를 사용하면 (E)\'날카로운 가시\'를 실은 평타가 차단되니 결계가 끝난 뒤에 공격하세요. (E)\'그림자 돌진\'에 맞아 도발되면 스킬을 쓸 수 없으니, 쉔이 다가오면 돌진하기 전에 (W)\'흉포한 울부짖음\'으로 침묵을 거세요. 쉔이 도발을 사용하기 전에 (Q)\'파열\'을 맞춰서 진입을 방해하는 것이 좋아요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 라인에 합류하면 빠르게 라인을 밀어 포탑 압박을 이어가세요. 쉔의 체력이 낮을 때 (R)\'포식\'을 사용하면 처치 후 최대 체력을 높여 성장을 가속할 수 있어요. 쉔의 궁극기 사용 여부를 항상 확인하며 정글의 개입에 대비하세요.', item: '첫 코어로 리안드리의 고통을 선택해 적에게 지속적인 피해를 입히세요. 신발은 쉔의 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (E)\'그림자 돌진\'을 사용한 뒤에 점화를 섞어 킬각을 만들어보세요.' },
    '쉬바나': { lv1: '1~2레벨에는 (Q)\'잉걸불 일격\'의 넓은 공격 범위에 휘말리지 않도록 주의하며 거리를 조절하세요. (Q)\'파열\'을 사용하여 쉬바나가 접근할 때 지면을 파열시켜 이동을 방해하는 것이 좋아요.', lv3: '쉬바나가 (W)\'지옥불 방패\'를 사용하여 보호막을 얻으려 할 때 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 사용을 방해하세요. (E)\'용암 분출\'에 맞지 않도록 무빙하며 (Q)\'파열\'을 적중시켜 딜교환을 시작해요.', lv6: '쉬바나가 (R)\'용의 강림\'을 사용하여 저지 불가 상태로 날아올 때 무리하게 맞서지 마세요. (Q)\'파열\'로 적을 공중으로 띄운 뒤 (R)\'포식\'을 사용하여 고정 피해를 입히는 것이 킬각을 잡기에 좋아요. 라인을 빠르게 밀어 넣으며 정글러를 부르세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 선택하세요. 쉬바나의 스킬에 대응하기 위해 강인함이 필요하고 지속적인 마법 피해를 입히기 위해서예요.', spell: '점멸과 점화를 추천해요. (R)\'포식\'으로 적을 처치할 때 부족한 피해를 보충하고 (W)\'지옥불 방패\'의 체력 회복 효과를 감소시킬 수 있어요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 멀리서 견제하며 영혼 조각을 모아요. 스웨인이 (Q)\'죽음의 손길\'을 쏠 때 옆으로 피하며 (Q)\'파열\'을 맞춰 거리를 좁히세요. 초반에는 무리한 딜교보다는 미니언을 챙기며 체력을 보존하는 것이 중요해요.', lv3: '스웨인의 (E)\'속박명령\'은 파동이 돌아올 때 속박이 발생하니 방향을 보고 피하세요. 스웨인이 (W)\'제국의 눈\'으로 둔화를 걸면 (W)\'흉포한 울부짖음\'으로 스웨인이 스킬을 사용하지 못하게 방해하세요. (Q)\'파열\'로 스웨인을 띄우고 (E)\'날카로운 가시\'로 피해를 입히는 것이 좋아요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용하면 주변 적의 체력을 흡수하니 너무 오래 붙어 있지 마세요. 변신 중에는 흡수 범위 밖으로 물러났다가, 체력이 낮아진 순간 (Q)\'파열\'로 띄운 뒤 다가가 (R)\'포식\'으로 마무리하세요. 정글러와 함께 싸울 때는 (W)\'흉포한 울부짖음\'으로 (E)\'속박명령\' 사용을 막아 주세요.', item: '첫 코어로 리안드리의 고통을 가고 신발은 헤르메스의 발걸음을 선택하세요. 스웨인의 마법 피해를 줄이고 강인함을 얻기 위해서예요.', spell: '점멸과 점화를 추천해요. 스웨인의 (R)\'악의 승천\'을 통한 체력 회복을 억제해야 해요.' },
    '스카너': { lv1: '스카너가 (Q)\'부서진 대지/지반 돌출\'을 사용하여 압박할 때 거리를 유지하며 미니언을 받아먹어요. (Q)\'파열\'을 사용하여 상대의 접근을 막고 둔화를 걸어 거리를 조절해요. 초반의 강한 압박을 견디며 성장에 집중하는 것이 중요해요.', lv3: '스카너의 (W)\'대지의 수호자\' 보호막이 빠진 뒤에 딜교환을 시도하세요. 스카너가 (E)\'이쉬탈의 격돌\'로 돌진할 때 (Q)\'파열\'을 맞춰서 이동을 방해하면 좋아요. 가까이 붙는다면 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 흐름을 끊으세요.', lv6: '스카너의 (R)\'꿰뚫기\'는 제압이라서 그동안 스킬을 쓸 수 없으니 주의하세요. (R)\'포식\'을 활용해 체력을 키우거나 적을 처치하며 성장을 도모해요. (E)\'이쉬탈의 격돌\'로 벽에 부딪히지 않도록 위치 선정에 신경을 써요.', item: '판금 장화와 리안드리의 고통을 가세요. 스카너의 기본 공격 피해를 줄이기 위해 판금 장화를 선택하고 지속적인 피해를 위해 리안드리의 고통을 가요.', spell: '점멸과 점화를 추천해요. 점멸로 (E)\'이쉬탈의 격돌\'에 대응하고, 상대의 체력이 낮을 때 점화를 (R)\'포식\'과 함께 써서 마무리하세요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 독구름을 남기며 라인을 빠르게 밀어내요. 무리하게 쫓아가지 말고 (Q)\'파열\'을 사용해 거리 조절을 하며 막타를 챙기세요. 독구름 속에 들어가면 지속 피해를 입으니 위치 선정에 주의하세요.', lv3: '신지드가 다가올 때 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 (E)\'던져넘기기\' 사용을 방해하세요. (W)\'초강력 접착제\'가 깔린 지역에서는 둔화되어 움직이기 힘드니 빠르게 벗어나세요. (E)\'날카로운 가시\'를 묻힌 평타로 짧게 딜교환하고 다시 거리를 벌리세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 방어력과 체력 재생이 올라가니 정면 승부를 피하세요. (Q)\'파열\'로 띄운 뒤 (R)\'포식\'으로 마무리하여 체력을 성장시키는 것이 중요해요. 라인이 밀릴 때는 포탑 아래에서 버티며 정글러의 개입을 기다리세요.', item: '마법 피해와 둔화 효과를 줄이기 위해 헤르메스의 발걸음을 추천해요. 체력을 크게 높여 탱킹력을 올리고 (R)\'포식\'과 시너지를 내는 강철심장을 첫 코어로 가세요.', spell: '점멸과 순간이동을 추천해요. 신지드가 라인을 강하게 밀기 때문에 순간이동으로 손실을 줄이는 것이 중요해요.' },
    '신짜오': { lv1: '1~2레벨에는 상대가 세 번째 기본 공격마다 (P)\'결심\'으로 체력을 회복하니, 평타를 세 번 이어서 맞지 않게 거리를 유지하세요. (Q)\'파열\'은 사거리가 길어 먼저 맞히기 좋고 공중에 띄운 뒤 둔화까지 걸어서, 상대가 붙으려 할 때 끊어 주기 좋아요. 상대가 (Q)\'삼조격\'을 켜고 다가오면 세 번째 평타에 띄워지기 전에 걸어서 빠져 강화 평타를 헛되이 쓰게 만드세요.', lv3: '(W)\'흉포한 울부짖음\'은 사거리가 짧아 멀리서 들어오는 (E)\'무쌍돌격\'을 미리 막기는 어려우니, 상대가 붙은 뒤 (W)\'풍전참뢰\'를 쓰기 전에 침묵을 맞혀 그 스킬을 못 쓰게 하세요. 이미 시작된 돌진은 침묵으로 끊기지 않으니 붙을 때는 (E)\'날카로운 가시\'를 켠 평타로 둔화를 걸어 맞받아치세요. 상대가 (Q)\'삼조격\' 세 번째 공격을 맞히기 전에 (Q)\'파열\'로 먼저 띄워서 딜교환을 끝내고 빠지세요.', lv6: '상대가 (R)\'현월수호\'를 쓰면 창이 닿는 거리 밖에 있는 적의 공격에 피해를 입지 않으니, 그동안 멀리서 (Q)\'파열\'을 쓰지 말고 붙어서 싸우거나 효과가 끝날 때까지 기다리세요. 효과가 끝난 뒤 (Q)\'파열\'로 띄우고 (R)\'포식\'을 연계하면 방어력을 무시한 고정 피해로 마무리할 각을 볼 수 있어요. 상대는 (E)\'무쌍돌격\'으로 정글러와 함께 빠르게 붙을 수 있으니, 라인을 밀어 둔 상태라면 시야를 확보하세요.', item: '균열 생성기와 판금 장화를 추천해요. 균열 생성기는 주문력과 체력을 함께 주어 전투가 길어질수록 (Q)\'파열\'과 (E)\'날카로운 가시\' 피해를 늘려 주고, 판금 장화는 (P)\'결심\'과 (Q)\'삼조격\'이 얹히는 상대의 기본 공격 피해를 줄여 줘요.', spell: '점멸과 점화를 추천해요. 점화는 (P)\'결심\'으로 회복하는 상대의 체력 회복 효과를 줄여 주고 마무리 피해도 보태 줘요. 점멸은 (E)\'무쌍돌격\'으로 붙거나 (Q)\'삼조격\' 세 번째 공격이 들어오기 전에 거리를 벌리는 데 쓰세요.' },
    '아이번': { lv1: '(Q)\'덩굴뿌리\'는 처음 맞은 적에게만 적중하니 미니언 뒤에 숨어 피해를 최소화하세요. (Q)\'파열\'로 미니언과 함께 상대를 맞추며 서서히 거리를 좁히고 (P)\'육식\'으로 체력을 관리하세요.', lv3: '(Q)\'덩굴뿌리\'에 속박되어도 스킬 사용이 가능하니 (W)\'흉포한 울부짖음\'을 써서 상대의 추가 스킬 사용을 막으세요. (E)\'날카로운 가시\'의 둔화를 이용해 거리를 좁힌 뒤 (Q)\'파열\'을 적중시켜 강하게 압박하세요.', lv6: '(R)\'데이지!\'의 충격파에 공중으로 띄워지지 않도록 주의하며 거리를 조절하세요. 상대의 주요 스킬이 빠진 틈을 타 (R)\'포식\'으로 체력이 낮은 아이번을 처치하고 성장을 챙기세요. 정글러가 올 때는 (Q)\'파열\'로 적의 진입을 끊어 아군을 보호하세요.', item: '헤르메스의 발걸음과 강철심장을 추천해요. 마법 저항력과 강인함으로 (Q)\'덩굴뿌리\'의 속박 시간을 줄이고 높은 체력으로 생존력을 높이세요.', spell: '점멸과 점화를 추천해요. (R)\'포식\'과 연계해 빠르게 킬을 내기 좋고 강력한 마무리 피해를 입히기 위해 사용하세요.' },
    '아지르': { lv1: '(W)\'일어나라!\'를 통한 원거리 견제를 최대한 버티며 체력을 관리하세요. (Q)\'파열\'을 아껴두었다가 상대가 전진할 때 사용해 거리 조절을 방해하고 둔화시켜 압박하세요. 무리하게 진입하기보다 경험치를 챙기며 성장하는 것이 중요해요.', lv3: '(E)\'신기루\'로 도망가기 전에 (W)\'흉포한 울부짖음\'을 사용해 상대의 스킬 사용을 막으세요. 이후 (E)\'날카로운 가시\'를 섞은 기본 공격으로 둔화를 걸어 추격하며 피해를 입히세요. (Q)\'사막의 맹습\'의 둔화에 걸리면 무리하게 쫓지 말고 다음 기회를 노리세요.', lv6: '(R)\'포식\'의 고정 피해로 킬각을 잡되 상대의 (R)\'황제의 진영\'에 밀려나지 않도록 주의하세요. (Q)\'파열\'로 먼저 적중시킨 후 빠르게 접근해 스킬을 연계하는 것이 좋아요. 라인을 밀어 넣고 정글의 도움을 받아 상대가 타워 아래에서 고립되게 만드세요.', item: '헤르메스의 발걸음과 심연의 가면을 추천해요. 마법 저항력을 높여 (Q)\'사막의 맹습\' 피해를 줄이고 강인함으로 둔화 지속시간을 줄이기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 점멸로 순식간에 거리를 좁혀 (R)\'포식\'을 사용하고 순간이동으로 라인 복귀와 합류를 빠르게 하기 위해서예요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 견제하며 (P)\'암살자의 표식\' 원을 이용해 강화 평타를 노려요. (Q)\'오연투척검\'은 부채꼴로 날아가 미니언이 막아 주지 못하니 사거리 끝의 둔화에 걸리지 않게 거리를 조절하세요. 아칼리가 무리하게 다가오면 (Q)\'파열\'로 공중으로 띄워 피해를 주세요.', lv3: '(W)\'황혼의 장막\' 안에서는 아칼리를 대상으로 지정할 수 없으니, 범위 공격인 (Q)\'파열\'이나 (W)\'흉포한 울부짖음\'으로 대응하세요. (E)\'표창곡예\' 표식이 남으면 재사용으로 돌진해 들어오니, 돌진을 시작하기 전에 (W)\'흉포한 울부짖음\'으로 침묵시키세요. (E)\'날카로운 가시\'가 켜진 상태에서 평타를 쳐서 둔화를 걸면 아칼리의 추격을 늦출 수 있어요.', lv6: '(R)\'무결처형\'을 다시 사용해 돌진하는 공격은 잃은 체력에 비례해 큰 피해를 주니 체력 관리에 신경 쓰세요. (R)\'포식\'은 대상 지정 스킬이라 (W)\'황혼의 장막\' 안의 아칼리에게는 쓸 수 없으니 연막 밖으로 나올 때 사용하세요. 라인을 밀어 넣고 포탑 근처에서 (Q)\'파열\'로 띄운 뒤 (R)\'포식\'으로 마무리하는 구도를 만드세요.', item: '심연의 가면을 첫 코어로 가서 체력과 마법 저항력을 챙기고 주변 적이 입는 마법 피해를 늘리세요. 신발은 아칼리의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진으로 아칼리가 진입했을 때 입히는 피해량을 줄이면 생존 확률이 높아져요.' },
    '아크샨': { lv1: '아크샨의 (Q)\'복수의 부메랑\' 사거리가 길어 초반에는 거리를 두며 미니언을 챙겨요. (Q)\'파열\'로 아크샨이 다가올 때 맞춰 띄우고 거리를 조절하며 대응해요.', lv3: '아크샨이 (E)\'영웅의 비상\'으로 진입하면 (Q)\'파열\'을 사용하여 공중으로 띄우는 것이 중요해요. 아크샨의 (Q)\'복수의 부메랑\'을 피하며 (W)\'흉포한 울부짖음\'으로 침묵을 걸면 딜교환을 시도할 수 있어요.', lv6: '아크샨의 (R)\'인과응보\'는 잃은 체력에 비례해 피해를 주므로 체력 관리에 주의해요. (R)\'포식\'을 사용하여 체력을 키우며 버티고, 아크샨의 체력이 낮을 때 (Q)\'파열\'과 (R)\'포식\'을 연계해 킬각을 노리며 라인을 관리해요.', item: '판금 장화와 강철심장을 추천해요. 아크샨의 기본 공격 피해를 줄이고 체력을 높여 버티기 좋기 때문이에요.', spell: '점멸과 점화. 아크샨의 체력이 낮아졌을 때 (R)\'포식\'과 함께 점화를 사용해 확정적으로 처치하기 위해서예요.' },
    '아트록스': { lv1: '(Q)\'다르킨의 검\'의 끝자락에 맞으면 공중으로 띄워지니 범위 밖으로 움직이거나 아예 안쪽으로 붙으세요. (P)\'사신 태세\'가 켜진 평타는 체력 회복과 추가 피해가 붙으니 평타 교환은 짧게 하세요. 상대가 진입할 때 (Q)\'파열\'을 사용해 공중으로 띄워 흐름을 끊어주세요.', lv3: '(W)\'지옥사슬\'에 맞으면 범위 밖으로 빠르게 벗어나 중앙으로 끌려가는 피해를 피하세요. 아트록스가 (E)\'파멸의 돌진\'으로 거리를 좁히면 (W)\'흉포한 울부짖음\'을 써서 스킬 사용을 잠시 막으세요. 이후 (Q)\'파열\'로 띄우고 (E)\'날카로운 가시\'가 묻은 평타를 쳐서 둔화를 거세요.', lv6: '(R)\'세계의 종결자\'를 사용한 아트록스는 체력 회복량이 대폭 늘어나니 정면 대결은 피하고 거리를 벌리세요. 상대의 궁극기 지속시간이 끝난 뒤 (Q)\'파열\'로 띄우고 (R)\'포식\'의 고정 피해로 체력을 한 번에 깎아내세요. 라인 관리 시 (E)\'파멸의 돌진\'을 활용한 갱킹 호응에 주의하며 뒤로 물러나세요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화로 기본 공격 피해를 줄이고 가시 갑옷의 치유 감소 효과로 (P)\'사신 태세\'와 (E)\'파멸의 돌진\' 회복을 억제하세요.', spell: '점멸과 점화를 추천해요. (P)\'사신 태세\'와 (E)\'파멸의 돌진\'을 통한 회복량이 매우 높으므로 점화의 치유 감소 효과가 킬각을 잡는 데 중요해요.' },
    '암베사': { lv1: '암베사가 (P)\'용사냥개의 발걸음\'으로 짧게 돌진하며 접근할 때 (Q)\'파열\'을 사용하여 진입을 방해하세요. 1~2레벨에는 암베사의 (Q)\'교활한 휩쓸기\' 범위에 맞지 않도록 거리를 조절하며 미니언을 받아먹으세요.', lv3: '암베사가 (W)\'배척\'을 준비하며 보호막을 얻을 때는 공격을 멈추고 암베사가 스킬을 끝낼 때까지 기다리세요. (E)\'찢어 가르기\'로 둔화가 걸리면 (W)\'흉포한 울부짖음\'을 사용하여 암베사가 스킬을 쓰지 못하게 막으며 거리를 조절하세요.', lv6: '암베사의 (R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 적에게 순간 이동해 제압하고, 제압 중에는 아무것도 할 수 없으니 체력이 낮을 때는 거리를 넉넉히 벌리세요. 암베사의 체력이 낮을 때 (R)\'포식\'을 사용하여 고정 피해로 처치하고 성장을 이어가세요. 정글러가 개입할 때는 (Q)\'파열\'로 암베사를 띄워 호응하세요.', item: '첫 코어로 강철심장을 가서 체력을 높이고 성장을 도모하세요. 신발은 암베사의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사가 (P)\'용사냥개의 발걸음\'으로 붙었을 때 점멸로 대응하고 체력이 낮은 암베사를 점화로 마무리하세요.' },
    '애니비아': { lv1: '1~2레벨 구간 애니비아는 (Q)\'냉기 폭발\' 구체를 날려 맞은 적에게 피해를 주고 폭발하면 기절시켜서 초반 견제가 강해요. 구체가 날아오는 궤적을 보고 옆으로 움직여 피해를 피하며 다가가세요. (Q)\'파열\'로 애니비아의 움직임을 방해하며 미니언을 챙기는 것이 좋아요.', lv3: '스킬이 모인 3레벨 이후에는 애니비아가 (W)\'결정화\' 벽을 세우면 접근 경로가 차단되니 벽이 생기기 전에 다가가세요. (Q)\'냉기 폭발\'에 맞으면 (E)\'동상\' 피해가 두 배로 늘어나니 냉각 상태일 때는 거리를 두어야 해요. 애니비아의 (Q)\'냉기 폭발\'이 빠진 타이밍에 (Q)\'파열\'을 맞춰 접근한 뒤 (W)\'흉포한 울부짖음\'으로 침묵을 거세요.', lv6: '6레벨 이후 애니비아가 (R)\'얼음 폭풍\'을 사용하면 범위 안에서 둔화와 피해를 입으니 장판 밖에서 싸우는 것이 좋아요. 애니비아는 치명적인 피해를 입으면 (P)\'환생\'으로 알이 되어 체력을 회복하니, (P)\'환생\'이 남아 있는지 확인하고 알까지 깨뜨릴 수 있을 때 (R)\'포식\'으로 킬각을 보세요. 정글러가 왔을 때 (Q)\'파열\'로 애니비아를 띄워 킬각을 노리는 것이 좋아요.', item: '애니비아의 마법 피해에 대비해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템으로는 마법 저항력과 스킬 가속을 제공하는 심연의 가면을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화는 이동 속도를 높이고 유닛과의 충돌을 무시해 거리를 좁히기 좋지만 둔화를 없애 주지는 않으니 (Q)\'냉기 폭발\'을 먼저 피하세요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'으로 견제하며 (P)\'낭인의 길\' 보호막을 통해 피해를 흡수해요. (E)\'날카로운 가시\'를 활성화한 평타로 보호막을 먼저 걷어내고 짧게 딜교환을 하세요. (Q)\'강철 폭풍\'의 회오리바람에 띄워지지 않도록 거리 조절에 신경 쓰며 파밍하세요.', lv3: '야스오가 (E)\'질풍검\'으로 빠르게 진입하면 (W)\'흉포한 울부짖음\'을 사용해 침묵시켜 스킬 연계를 끊으세요. (W)\'바람 장막\'은 투사체만 막으니 (Q)\'파열\'과 (W)\'흉포한 울부짖음\'은 장막이 있어도 그대로 맞힐 수 있어요. (Q)\'파열\'의 둔화 효과를 이용해 야스오가 다시 진입하기 어렵게 만드세요.', lv6: '야스오의 (R)\'최후의 숨결\'은 공중에 뜬 적 챔피언에게 쓰는 스킬이니 (Q)\'강철 폭풍\' 회오리바람이나 상대 정글러의 띄우기에 걸리지 않게 주의하세요. 체력이 낮아진 야스오에게 (R)\'포식\'을 사용하여 처치하고 최대 체력을 쌓아 성장하세요. 라인을 당겨서 (W)\'흉포한 울부짖음\'과 (Q)\'파열\' 연계로 정글러와 함께 잡아내세요.', item: '강철심장을 첫 코어로 선택해 최대 체력을 높여 야스오의 물리 피해를 버텨내세요. 신발은 야스오의 기본 공격 피해를 줄여 주는 판금 장화가 효율적이에요.', spell: '점멸과 순간이동을 추천해요. (Q)\'파열\'을 빗맞혔을 때 점멸로 거리를 좁히거나 순간이동으로 빠르게 라인에 복귀하여 성장을 유지하세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리를 늘려 공격하며 (P)\'바위 피부\'로 방어력을 높여요. 정면에서 오래 싸우면 오공이 편해지니 (Q)\'파열\'을 이용해 거리를 유지하며 견제하세요. 첫 웨이브부터 무리하게 붙지 말고 상대의 체력을 조금씩 깎아두는 것이 좋아요.', lv3: '(E)\'근두운 급습\'으로 돌격해 들어올 때 (Q)\'파열\'로 공중에 띄워 흐름을 끊어주세요. 오공이 (W)\'분신 전사\'로 숨어 들어오면 (W)\'흉포한 울부짖음\'으로 침묵시켜 다음 스킬 사용을 막으세요. (E)\'날카로운 가시\'의 둔화를 활용해 오공이 쉽게 도망가지 못하게 압박하세요.', lv6: '(R)\'회전격\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 오공이 궁극기를 사용한 뒤에 진입하세요. 체력이 낮은 오공에게 (R)\'포식\'을 사용해 처치하고 성장을 챙기는 것이 중요해요. 오공의 돌진기에 맞춰 정글러가 들어오기 쉬우니 라인을 당겨서 관리하세요.', item: '강철심장을 첫 코어로 가서 최대 체력을 높여 (R)\'포식\'과 시너지를 내세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'바위 피부\'의 체력 재생 효과를 줄이고 확실하게 마무리하세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 사용해 원거리에서 견제하니 스킬이 되돌아오는 경로를 옆으로 피해 주세요. (Q)\'파열\'을 적중시켜 오로라를 공중으로 띄우면 견제 흐름을 끊고 체력을 보존할 수 있어요. 첫 웨이브는 무리하게 진입하지 말고 경험치 위주로 챙기세요.', lv3: '(E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하는 오로라를 무리하게 쫓지 마세요. (W)\'흉포한 울부짖음\'으로 침묵을 먼저 걸면 오로라가 (W)\'장막 너머로\'를 사용해 투명해지는 것을 방지할 수 있어요. (E)\'날카로운 가시\'를 켜고 기본 공격을 맞춰 이동 속도를 늦추며 딜교환하세요.', lv6: '(R)\'세계의 경계\' 영역 안에서는 오로라의 기동력이 매우 좋으니 영역 밖으로 빠르게 벗어나세요. (Q)\'파열\'로 오로라를 띄운 뒤 체력이 낮은 순간 (R)\'포식\'으로 처치해 성장을 노리세요. 오로라는 (W)\'장막 너머로\'로 도망칠 수 있으니 정글러를 부를 때 주의하세요.', item: '심연의 가면을 첫 코어로 선택해 마법 저항력을 높이고 주변 적이 받는 마법 피해를 증가시키는 파괴 효과를 활용하세요. 신발은 오로라의 마법 피해를 줄이고 둔화 지속시간을 낮추는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'을 통해 체력을 회복하므로 점화의 치유 감소 효과로 이를 억제하세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 기본 저항력이 높아서 초반 짧은 교환으로는 체력이 잘 안 깎여요. (Q)\'용암 균열\'의 균열 위치를 잘 보고 용암 기둥이 솟기 전에 옆으로 피하세요. 적절한 거리에서 (Q)\'파열\'을 사용해 오른의 접근을 방해하며 막타를 챙기세요.', lv3: '벽 근처에 있으면 (E)\'화염 돌진\'에 맞아 공중으로 띄워지니 탁 트인 곳에서 싸우세요. (W)\'불꽃 풀무질\'의 마지막 타격을 맞아 불안정 상태가 되면 군중 제어 지속시간이 늘어나니 주의하세요. 오른이 진입할 때 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 스킬 연계를 끊고 (E)\'날카로운 가시\'를 묻힌 평타로 응수하세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령이 박치기하며 다가올 때 옆으로 피해서 공중으로 띄워지는 것을 막으세요. 오른의 체력이 낮아졌을 때 (R)\'포식\'을 사용하면 방어력을 무시한 고정 피해를 입혀 마무리할 수 있어요. 오른은 (P)\'간이 대장간\'으로 아이템을 빠르게 완성하니 무리한 킬각보다는 (Q)\'파열\'로 정글러의 개입을 돕는 것이 좋아요.', item: '강철심장을 첫 코어로 선택해 체력을 높이고 (R)\'포식\'의 효율을 올리세요. 신발은 오른의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 튼튼해서 빠르게 잡기 어려우니 순간이동으로 라인 손실을 줄이며 성장하세요.' },
    '올라프': { lv1: '1~2레벨에는 올라프가 (Q)\'역류\'를 던지고 도끼를 주우러 올 때 거리를 벌리며 (Q)\'파열\'로 견제하세요. 올라프의 (P)\'광전사의 분노\' 때문에 체력이 낮아지면 공격 속도와 흡혈이 늘어나니 주의해야 해요. 미니언을 먹으며 최대한 거리를 유지하며 버티는 것이 중요해요.', lv3: '올라프가 (W)\'버티기\'를 사용해 보호막을 얻으면 딜교환을 잠시 멈추고 기다리세요. (W)\'흉포한 울부짖음\'을 사용하여 올라프가 스킬을 쓰지 못하게 침묵시키고 (Q)\'파열\'로 둔화를 걸어 거리를 벌리세요. (E)\'날카로운 가시\'를 활용해 지속적으로 피해를 입히며 올라프의 접근을 방해하세요.', lv6: '올라프가 (R)\'라그나로크\'를 쓰는 동안에는 이동 불가와 방해 효과에 면역이라 (Q)\'파열\' 띄우기를 노리기 어려우니 무리하게 맞서지 마세요. (R)\'라그나로크\'가 끝난 뒤에 (Q)\'파열\'로 띄우고 (R)\'포식\'으로 마무리하는 것이 안전해요. 정글러가 올 때 올라프가 궁극기로 이동 불가 및 방해 효과에 면역이 되어 들어올 수 있으니 라인을 너무 깊게 밀지 마세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 올라프의 기본 공격 피해를 줄여주고 리안드리의 고통은 지속적인 마법 피해를 입히기에 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 올라프의 (P)\'광전사의 분노\' 흡혈을 억제하세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 두 번 맞히면 돌진하며 공중으로 띄워 올려요. 첫 번째 (Q)\'필멸의 검\'을 맞았다면 거리를 벌려 두 번째 돌풍을 피하세요. (P)\'사냥꾼의 길\' 때문에 평타 교환을 길게 하면 손해이니 짧게 딜교환하세요.', lv3: '요네가 (E)\'영혼해방\'으로 진입할 때 (W)\'흉포한 울부짖음\'을 써서 상대의 스킬 사용을 막으세요. (W)\'영혼 가르기\' 보호막이 생성된 동안에는 피해를 덜 입히니 보호막이 사라진 뒤에 (E)\'날카로운 가시\'로 공격하세요. 요네의 (Q)\'필멸의 검\' 돌풍이 예상되는 지점에 (Q)\'파열\'을 써서 진입을 끊어주세요.', lv6: '요네의 (R)\'운명봉인\'은 적을 끌어당기며 공중으로 띄우니 팀원과 너무 가깝게 붙어 있지 마세요. 요네의 체력이 낮아졌을 때 (R)\'포식\'으로 확실하게 마무리하여 체력을 성장시키세요. (R)\'운명봉인\' 이후 요네가 돌아가는 위치를 예상해 (Q)\'파열\'을 맞히면 정글 개입 상황에서 대처하기 편해요.', item: '판금 장화를 선택해 요네의 기본 공격 피해를 줄이세요. 강철심장을 첫 코어로 올려 최대 체력을 높이고 (R)\'포식\'과 함께 성장 효율을 높이세요.', spell: '점멸과 순간이동을 추천해요. 요네의 강한 진입력을 버티며 라인 복귀를 빠르게 해야 하기 때문이에요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 무덤을 만들고 (P)\'영혼의 길잡이\'로 안개 망령을 소환해 공격해요. (Q)\'파열\'을 사용해 요릭과 망령을 동시에 공중으로 띄워 피해를 입히고 거리를 조절하세요. 초반에는 무리하게 붙기보다 미니언 뒤에서 (Q)\'파열\'로 견제하며 체력 관리에 집중하세요.', lv3: '요릭이 (E)\'애도의 안개\'를 맞히면 망령들이 몰려오니 즉시 (W)\'흉포한 울부짖음\'으로 요릭의 스킬 사용을 막아 (W)\'망자의 진\' 설치를 방해하세요. (E)\'날카로운 가시\'의 둔화와 피해를 이용해 다가오는 안개 망령들을 빠르게 정리하며 싸우는 것이 중요해요. (W)\'망자의 진\' 벽에 갇혔을 때는 당황하지 말고 빠르게 평타로 벽을 부수고 빠져나오세요.', lv6: '(R)\'군도의 장송곡\'으로 안개 마녀가 나오면 피해량이 크게 늘어나니 마녀의 표식이 남지 않도록 주의하며 짧게 교환하세요. 체력이 낮아진 요릭에게 (R)\'포식\'을 사용해 큰 고정 피해를 입히고 처치하여 최대 체력을 성장시키세요. 요릭이 안개 마녀와 망령으로 라인을 빠르게 밀어내니 포탑 앞에서 웨이브를 관리하며 정글의 도움을 기다리세요.', item: '물리 피해와 기본 공격을 줄여주는 판금 장화와 주변 적에게 지속 피해를 주는 태양불꽃 방패를 추천해요. 안개 망령들이 붙었을 때 태양불꽃 방패의 효과로 함께 정리하기 편해요.', spell: '점멸과 점화를 추천해요. (Q)\'최후의 의식\'으로 회복하는 요릭의 체력 재생을 점화로 억제해 킬각을 잡으세요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 빠르게 다가오면 (Q)\'파열\'을 사용하여 접근을 늦추세요. 1~2레벨에는 우디르의 기본 공격이 강력하니 최대한 거리를 유지하며 (Q)\'파열\'로 견제하는 것이 좋아요. 우디르가 (E)\'불길 쇄도\'로 돌진해 들어오지 못하게 주의하세요.', lv3: '우디르가 (W)\'강철 갑옷\'을 사용하려 할 때 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 사용을 막으세요. (E)\'불길 쇄도\'의 기절을 맞았다면 무리하게 싸우지 말고 뒤로 물러나야 해요. 우디르의 (E)\'불길 쇄도\' 기절이 빠진 것을 확인한 뒤 (E)\'날카로운 가시\'를 섞어 짧게 딜교환을 하세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 사용해 주변에 둔화를 걸면 (Q)\'파열\'로 띄워 거리를 벌리세요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 효과에 면역이 된 상태라면 (W)\'흉포한 울부짖음\'을 아끼세요. 우디르의 체력이 낮아졌을 때 (R)\'포식\'을 사용하여 확실하게 처치하고 성장을 이어가세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속적인 마법 피해를 입히세요. 신발은 우디르의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복하기 전에 점화를 사용해 회복량을 줄이세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 견제하려 하니 사거리를 조절하며 첫 웨이브를 받아내세요. (Q)\'파열\'은 우르곳이 다가올 때 맞춰 사용하여 거리를 벌리는 용도로 쓰면 좋아요. 무리하게 맞딜을 하기보다 체력을 보존하며 성장에 집중하세요.', lv3: '우르곳이 (E)\'경멸\'로 돌진해 뒤로 던지는 것을 조심하며 돌진 방향을 예측해 피하세요. (E)\'경멸\'이 빠진 직후 (Q)\'파열\'을 맞춰 공중으로 띄우고 (W)\'흉포한 울부짖음\'으로 스킬 사용을 막으며 딜교환을 하세요. (W)\'심판의 원\'을 켠 상태의 우르곳과는 정면 대결을 피하는 것이 좋아요.', lv6: '우르곳의 (R)\'불사의 공포\' 섬광탄에 맞은 상태에서 체력이 낮으면 제압당하고 처형될 수 있으니 주의하세요. (Q)\'파열\'로 우르곳을 공중으로 띄운 뒤 (R)\'포식\'을 사용하면 큰 고정 피해를 입히며 킬각을 잡을 수 있어요. 정글러의 개입에 대비해 라인을 너무 밀지 않도록 관리하세요.', item: '첫 코어로 리안드리의 고통을 가서 체력이 높은 우르곳에게 지속 피해를 입히세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳의 체력이 낮을 때 점화로 마무리 피해를 더해 킬을 가져오세요.' },
    '워윅': { lv1: '1~2레벨에는 워윅이 (Q)\'야수의 송곳니\'로 도약해 체력을 회복하며 들어오니 주의해야 해요. 워윅이 접근할 때 (Q)\'파열\'을 사용하여 이동을 방해하며 거리를 유지하는 것이 중요해요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 인해 회복량이 크게 늘어나니 무리하게 맞붙지 마세요.', lv3: '워윅이 (E)\'원시의 포효\'를 켜면 받는 피해가 줄고 끝날 때 주변 적을 공포에 빠뜨리니, 켜는 것을 보면 공포 범위 밖으로 물러났다가 효과가 끝난 뒤에 다시 교환하세요. 워윅의 (Q)\'야수의 송곳니\'를 피한 뒤 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 스킬 사용을 막으며 딜교환을 시도하세요. (E)\'날카로운 가시\'를 활용해 지속적으로 둔화를 걸어 워윅이 붙기 어렵게 만드세요.', lv6: '워윅이 (R)\'무한의 구속\'으로 달려들어 제압을 걸면 정화로도 풀 수 없으니 정글러가 근처에 있을 때는 라인을 당겨 두세요. 워윅의 체력이 낮아 (W)\'피의 사냥\' 효과가 활성화된 상태라면 (R)\'포식\'을 사용해 한 번에 처치하는 것을 노리세요. 워윅의 궁극기가 빠진 시점에는 (Q)\'파열\'과 (E)\'날카로운 가시\'를 연계해 압박을 가하며 성장을 이어가세요.', item: '워윅의 마법 피해와 군중 제어 효과를 견디기 위해 헤르메스의 발걸음을 신으세요. 지속적인 피해를 주기 위해 리안드리의 고통을 첫 코어 아이템으로 선택해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'에 의한 체력 회복을 억제하세요.' },
    '이렐리아': { lv1: '이렐리아가 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오며 체력을 회복할 수 있으니 미니언 근처에서 거리를 조절하세요. 이렐리아가 진입하려 할 때 (Q)\'파열\'을 사용하여 공중으로 띄우면 진입을 방해할 수 있어요. 1~2레벨에는 무리한 교환을 피하고 안정적으로 성장하는 것이 중요해요.', lv3: '이렐리아의 (E)\'쌍검협무\'가 맞으면 기절하니 칼날이 지나가는 길목을 잘 피해야 해요. (W)\'저항의 춤\'을 충전하는 동안에는 이렐리아가 행동할 수 없고 받는 피해가 줄어드니 그동안은 스킬을 아끼고 발사 방향에서 비켜서세요. 이후 (W)\'흉포한 울부짖음\'으로 침묵을 걸어 다음 스킬 연계를 막고 (E)\'날카로운 가시\'로 딜교환하세요.', lv6: '이렐리아가 (R)\'선봉진격검\'을 사용하여 결계를 만들면 둔화 피해를 입으니 결계 안으로 들어가지 마세요. 이렐리아의 체력이 낮을 때 (R)\'포식\'을 사용하면 방어력을 무시하는 고정 피해로 확실하게 마무리할 수 있어요. 라인을 너무 밀어두면 이렐리아가 미니언을 타고 다시 접근하기 쉬우니 주의하세요.', item: '판금 장화와 강철심장을 추천해요. 판금 장화는 이렐리아의 기본 공격 피해를 줄여주고 강철심장은 체력을 높여 전투를 지속하기 좋게 해줘요.', spell: '점멸과 점화를 추천해요. 점화는 이렐리아의 (Q)\'칼날 쇄도\'를 통한 체력 회복 효과를 감소시켜서 킬각을 잡기 편하게 해줘요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에 촉수를 소환하니 최대한 라인 중앙에서 싸우세요. (Q)\'파열\'을 사용해 적절한 거리를 유지하며 견제하고, 일라오이가 다가올 때 둔화를 걸어 접근을 늦추세요. (Q)\'촉수 강타\'의 사거리 밖에서 미니언을 챙기며 피해를 최소화하세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 일라오이가 분리된 영혼을 때릴 때 피해 일부가 나에게 들어오고, 영혼에서 멀어지면 숙주가 되어 촉수가 소환되니 벽에서 떨어진 쪽으로 빠지세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약해 붙으려 할 때 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 연계를 끊어내세요. (E)\'날카로운 가시\'를 활용해 짧게 딜교환을 하되 촉수가 많은 지형은 피하세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용하면 순식간에 많은 촉수가 생기니 즉시 거리 조절을 하며 범위를 벗어나세요. 상대의 스킬이 빠진 틈을 타 (Q)\'파열\'로 띄운 뒤 (R)\'포식\'으로 마무리하여 체력을 성장시키세요. 일라오이는 정글러와 함께 싸울 때 더 많은 촉수를 소환하니 라인을 당겨서 개입에 대비하세요.', item: '판금 장화와 강철심장을 추천해요. 판금 장화로 일라오이의 기본 공격 피해를 줄이고, 강철심장으로 체력을 높여 (R)\'포식\'과 함께 성장 효율을 극대화하세요.', spell: '점멸과 순간이동을 추천해요. 일라오이의 (E)\'영혼의 시험\' 사거리에서 빠르게 벗어나거나 라인 복귀를 통해 손실을 줄이세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 팔을 뻗어 붙잡고 (P)\'세포 분열\' 조각을 흡수해 체력을 회복해요. (Q)\'탄성 주먹\'에 붙잡히지 않게 거리를 유지하고, 자크가 조각을 주우러 다가올 때 (Q)\'파열\'로 띄워 둔화를 거세요. 1~2레벨에는 (E)\'날카로운 가시\'를 활용해 짧은 평타 교환으로 체력을 깎아두는 것이 좋아요.', lv3: '(E)\'새총 발사\'로 진입하는 자크가 착지하는 지점에 (Q)\'파열\'을 써서 공중에 띄우면 진입 흐름을 끊을 수 있어요. 자크가 (W)\'불안정 물질\'을 터뜨리려 근접했을 때 (W)\'흉포한 울부짖음\'을 사용해 침묵시키면 다음 스킬 연계를 막을 수 있어요. (E)\'날카로운 가시\'의 둔화를 이용해 자크가 조각을 흡수하러 오는 경로를 방해하며 일방적으로 공격하세요.', lv6: '(R)\'바운스!\'는 여러 번 튀어 오르며 띄우고 둔화를 거니, 적중당해 공중에 뜨면 스킬을 쓸 수 없으므로 주의하세요. 자크는 쓰러져도 (P)\'세포 분열\'로 조각이 남아 부활하니 (R)\'포식\'으로 처치한 뒤 남은 조각까지 공격해 부활을 막으세요. (Q)\'파열\'로 띄운 뒤 (W)\'흉포한 울부짖음\'과 (E)\'날카로운 가시\'를 섞어 딜교환하고 정글러가 올 때 (Q)\'파열\'로 진입을 늦추세요.', item: '체력을 크게 올리는 강철심장을 첫 코어로 가서 성장 기대치를 높이세요. 신발은 (W)\'불안정 물질\'의 마법 피해를 줄이고 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 자크의 (P)\'세포 분열\' 회복량을 줄여 킬각을 잡기 편해요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 정면에서 평타를 오래 주고받지 마세요. (Q)\'파열\'을 사용해 적절한 거리를 유지하며 견제하고 자헨이 다가오지 못하게 하세요. 1~2레벨에는 짧게 딜교환을 하고 빠르게 뒤로 물러나세요.', lv3: '(W)\'공포의 귀환\'에 끌려가면 위험하니 자헨의 전진 방향에서 벗어나세요. 자헨이 (E)\'찬란한 쇄도\'로 진입하면 (W)\'흉포한 울부짖음\'으로 침묵시켜 다음 스킬 연계를 끊어주세요. (E)\'날카로운 가시\'를 켠 평타로 자헨을 둔화시켜 추격을 늦추고 천천히 거리를 벌리세요.', lv6: '(R)\'단호한 판결\'로 날아오를 때 낙하 지점에서 빠르게 벗어나 피해와 회복을 막으세요. 자헨이 착지한 직후 (R)\'포식\'을 사용하여 체력이 낮은 적을 마무리하고 체력을 챙기세요. (P)\'전쟁 단련\' 결심이 가득 차면 부활할 수 있으니 완전히 처치될 때까지 방심하지 마세요.', item: '가시 갑옷을 첫 코어로 선택해 자헨의 회복을 억제하고 공격해 오는 자헨에게 마법 피해를 돌려주세요. 신발은 자헨의 강력한 평타 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨이 (Q)\'다르킨의 글레이브\'와 궁극기로 체력을 회복하니 점화의 치유 감소 효과가 필요해요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 붙어 (P)\'가차없는 맹공\'을 쌓기 전에 (Q)\'파열\'로 거리를 조절하세요. 1~2레벨에는 잭스의 기본 공격이 강하니 (Q)\'파열\'의 둔화 효과를 활용해 잭스의 진입을 늦추며 견제해요.', lv3: '잭스가 (E)\'반격\'을 쓰는 동안은 기본 공격을 회피하니 그동안은 공격을 아끼고 거리를 유지하세요. (W)\'무기 강화\'를 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵시키면 스킬 연계를 막을 수 있어요. (E)\'반격\'의 기절이 끝난 뒤 (E)\'날카로운 가시\'로 딜교환을 하세요.', lv6: '잭스가 (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력이 높아지면 정면 대결을 피하세요. 잭스의 (E)\'반격\'이 끝나고 들어오는 타이밍에 (R)\'포식\'을 사용하여 고정 피해로 처치할 준비를 해요.', item: '판금 장화를 구매해 잭스의 기본 공격 피해를 줄이세요. 첫 코어 아이템으로는 리안드리의 고통을 선택해 지속적인 피해를 입혀요.', spell: '점멸과 점화를 추천해요. 잭스가 (Q)\'도약 공격\'으로 붙었을 때 점멸로 거리를 조절하고 점화로 마무리 피해를 입혀요.' },
    '제이스': { lv1: '제이스가 캐논 형태의 (Q)\'전격 폭발\'로 견제할 때는 구체의 궤적에서 비켜서서 피하며 미니언을 챙기세요. 해머 형태로 (Q)\'하늘로!\'를 사용하며 다가올 때는 (Q)\'파열\'로 띄워 진입을 끊고, 무리하게 싸우지 말고 체력을 보존하세요.', lv3: '해머 형태 제이스가 (E)\'천둥 강타\'로 밀쳐내기 전에 (Q)\'파열\'을 맞춰 공중으로 띄우면 거리를 좁히기 쉬워요. 제이스가 스킬을 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞혀 침묵시킨 뒤 (E)\'날카로운 가시\'로 딜교환을 진행하세요.', lv6: '캐논 형태의 제이스는 멀리서 견제해 (R)\'포식\'을 바로 쓰기 어려우니, 해머 형태로 바꿔 다가올 때를 기다리세요. 제이스가 해머 형태로 접근할 때 (Q)\'파열\'로 띄운 뒤 (R)\'포식\'을 맞히면 킬을 노릴 수 있어요. 라인을 관리하며 정글러의 개입을 유도하세요.', item: '판금 장화와 리안드리의 고통을 가세요. 제이스의 물리 피해를 줄이고 지속적인 마법 피해를 입히기 위해서예요.', spell: '점멸과 점화를 추천해요. 제이스가 스킬을 사용한 뒤 도망갈 때 점멸로 거리를 좁혀 (R)\'포식\'을 맞히세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'로 이동 속도를 높여 진입하고 (P)\'적응형 방어 체계\'로 보호막을 얻어 교환을 시도해요. 보호막이 있을 때는 짧게 딜교환하고, 카밀이 다가올 때 (Q)\'파열\'을 사용해 공중으로 띄워 진입 흐름을 끊으세요. (Q)\'정확성 프로토콜\'의 추가 강화 공격이 나오기 전에 거리를 조절하는 것이 중요해요.', lv3: '(E)\'갈고리 발사\'에 맞아 기절하면 스킬을 쓸 수 없으니, 카밀이 벽에 붙는 것을 보면 착지 예상 지점에 미리 (Q)\'파열\'을 써 두세요. 카밀이 근접했을 때 (W)\'흉포한 울부짖음\'을 사용해 침묵시키면 (W)\'전술적 휩쓸기\'나 추가 공격 스킬을 쓰지 못하게 막을 수 있어요. (E)\'날카로운 가시\'를 켠 상태로 평타를 쳐서 카밀의 이동 속도를 늦추며 체력을 깎으세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 어떤 방법으로도 빠져나갈 수 없으니 카밀의 궁극기가 있을 때는 체력을 넉넉히 유지하고 정글러의 개입을 기다리세요. 카밀이 궁극기로 진입해 체력을 깎았더라도, 체력이 낮은 상태라면 (R)\'포식\'을 사용해 고정 피해로 한 번에 처치할 수 있어요. (Q)\'파열\'로 카밀의 진입 경로를 미리 견제하며 라인을 관리하고 정글러가 올 수 있는 공간을 확보하세요.', item: '강철심장을 첫 코어로 선택해 체력을 크게 높여 카밀의 폭발적인 피해를 버티세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화로 카밀의 (W)\'전술적 휩쓸기\'를 통한 체력 회복을 방해하고 킬각을 잡으세요.' },
    '카사딘': { lv1: '1~2레벨에는 (Q)\'무의 구체\'가 정신 집중을 끊고 보호막을 만들어 주니 맞지 않게 거리를 유지하세요. 카사딘의 스킬 사거리는 내 (Q)\'파열\'보다 짧으니 (Q)\'파열\'을 적중시켜 공중으로 띄우는 것에 집중하세요.', lv3: '(Q)\'파열\'로 상대를 띄운 뒤 (W)\'흉포한 울부짖음\'을 사용해 스킬 사용을 막으세요. 이후 (E)\'날카로운 가시\'가 묻은 기본 공격을 가해 둔화를 걸고 체력을 깎으세요. 상대의 (E)\'힘의 파동\'이 빠진 타이밍을 노려 딜교환을 시도하는 것이 좋아요.', lv6: '(R)\'균열 이동\'으로 빠르게 도망가므로 함부로 (R)\'포식\'을 쓰지 말고 체력이 낮을 때 결정적으로 사용하세요. (W)\'흉포한 울부짖음\'으로 침묵을 먼저 걸면 상대의 이동기를 막고 킬각을 잡기 편해요. 라인을 당겨 정글의 도움을 받으며 압박하세요.', item: '헤르메스의 발걸음과 강철심장을 가세요. 마법 저항력과 강인함으로 견제를 버티고 체력을 크게 늘려야 해요.', spell: '점멸과 순간이동을 추천해요. 카사딘이 (R)\'균열 이동\'으로 다른 라인에 합류하면 순간이동으로 따라가거나 라인 손해를 줄이세요.' },
    '카시오페아': { lv1: '카시오페아의 (Q)\'맹독 폭발\'은 잠시 후 터지니 독이 퍼지는 위치를 보고 옆으로 빠지며 견제를 줄이세요. (E)\'쌍독니\'는 중독된 상태에서 피해가 커지니 독에 맞았다면 무리하게 다가가지 말고, (Q)\'파열\'은 카시오페아가 미니언을 잡으러 앞으로 나올 때 노리세요.', lv3: '상대의 (W)\'독기의 늪\'이 깔리면 즉시 거리를 벌려 이동이 제한되지 않도록 주의하세요. (Q)\'파열\'을 적중시켜 카시오페아를 공중으로 띄운 뒤에 (W)\'흉포한 울부짖음\'으로 딜교환을 시도해요.', lv6: '(R)\'석화의 응시\'는 카시오페아를 바라보는 적을 기절시키니, 궁극기가 시작되면 등을 돌려 기절 대신 둔화만 받도록 하세요. (R)\'포식\'을 사용하여 체력을 높이며 버티고, (Q)\'파열\'을 활용해 정글러와 함께 킬각을 잡아요.', item: '마법 피해를 견디기 위해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템으로는 마법 저항력을 높여주는 심연의 가면을 추천해요.', spell: '점멸과 유체화를 추천해요. 카시오페아의 (W)\'독기의 늪\'에서 빠르게 벗어나거나 거리를 조절할 때 유체화가 큰 도움이 돼요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 (P)\'폭풍의 표식\'을 쌓아 기절시키려 해요. 수리검 사거리가 기니 미니언 뒤에서 대기하며 표식이 쌓이지 않게 주의하세요. (Q)\'파열\'을 맞히면 둔화시키고 (E)\'날카로운 가시\'를 묻혀 짧은 딜교환을 하세요.', lv3: '(E)\'번개 질주\'로 들어오는 케넨에게 (W)\'흉포한 울부짖음\'을 맞혀 스킬 사용을 막으세요. 침묵은 (W)\'전류 방출\' 사용만 막고 기본 공격에 붙는 표식은 막지 못하니 (P)\'폭풍의 표식\'이 쌓인 횟수를 세어 두세요. 표식이 많이 쌓였다면 무리하게 붙지 말고 거리를 벌리세요.', lv6: '(R)\'날카로운 소용돌이\'를 켠 케넨에게 다가가면 기절이 빠르게 쌓이니 즉시 거리를 벌리세요. (E)\'번개 질주\'가 빠진 상태에서 체력이 낮아졌다면 (R)\'포식\'으로 처치해 성장하세요. 정글 개입 시에는 (Q)\'파열\'로 적을 띄워 아군이 호응하기 편하게 만드세요.', item: '대자연의 힘을 첫 코어로 가서 마법 저항력을 높이고 피해를 줄이세요. 신발은 (P)\'폭풍의 표식\' 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (P)\'폭풍의 표식\'으로 인한 기절을 정화로 빠르게 풀 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 발동하기 전까지는 사거리가 짧고 약해요. (Q)\'파열\'로 케일을 띄워 딜교환을 시작하고, (Q)\'광휘의 일격\'에 맞지 않게 주의하며 압박하세요. 첫 웨이브부터 적극적으로 다가가서 체력을 깎아두는 것이 좋아요.', lv3: '(E)\'화염주문검\'은 체력이 낮을수록 큰 피해를 주니 내 체력이 적을 때 오래 싸우지 마세요. 케일이 (W)\'천상의 축복\'으로 회복하며 도망가기 전에 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 사용을 막으세요. (Q)\'파열\'을 맞힌 뒤 (E)\'날카로운 가시\'를 묻힌 기본 공격을 이어가며 체력을 깎으세요.', lv6: '(R)\'신성한 심판\'은 대상을 무적으로 만드니, 무적 효과가 끝나는 타이밍에 맞춰 (R)\'포식\'을 사용해 처치하세요. 무적 상태일 때는 어떤 스킬도 통하지 않으니 무턱대고 진입하지 말고 기다리세요. (Q)\'파열\'로 접근한 뒤 (W)\'흉포한 울부짖음\'으로 케일의 스킬 연계를 끊으며 정글러와 함께 잡으세요.', item: '마법 피해를 줄여주는 헤르메스의 발걸음과 체력 및 마법 저항력을 높여주는 심연의 가면을 추천해요. 케일의 지속적인 마법 피해를 견디며 버티기 위해서예요.', spell: '점멸과 점화를 추천해요. (W)\'천상의 축복\'의 회복량을 줄이고 초반에 빠르게 킬을 내어 성장을 방해하세요.' },
    '코그모': { lv1: '코그모의 (Q)\'부식성 침\'이 미니언에 막히도록 위치를 잡으며 피해를 줄여요. (Q)\'파열\'을 사용하여 코그모의 움직임을 제약하며 차분하게 성장에 집중하세요.', lv3: '코그모가 (W)\'생체마법 폭격\'을 사용하여 사거리가 길어진 상태에서는 무리하게 진입하지 마세요. 코그모의 (W)\'생체마법 폭격\'이 빠지면 (Q)\'파열\'로 적을 공중으로 띄우고 (W)\'흉포한 울부짖음\'을 맞춰 침묵을 입혀요. (E)\'날카로운 가시\'를 활용해 딜교환을 시도하세요.', lv6: '코그모의 (R)\'살아있는 곡사포\'는 체력이 낮은 적에게 큰 피해를 주니 주의하며 대응하세요. (R)\'포식\'을 사용하여 체력을 키우며 라인 주도권을 잡고 정글러의 개입을 유도하세요. (Q)\'파열\'로 코그모를 띄워 접근을 끊으며 압박하세요.', item: '헤르메스의 발걸음과 공허한 광휘를 가세요. 코그모의 마법 피해를 견디고 체력을 확보하기 위해서예요.', spell: '점멸과 점화를 추천해요. 점멸로 거리를 좁혀 (R)\'포식\'을 맞히고 점화로 코그모를 확실하게 마무리하세요.' },
    '코르키': { lv1: '코르키가 (Q)\'인광탄\'을 사용하여 견제할 때 위치를 잘 잡으며 피해를 최소화하세요. (Q)\'파열\'을 활용해 코르키의 접근을 늦추며 미니언을 챙기는 것이 중요해요. 1~2레벨 구간에는 무리하게 싸우기보다 체력을 관리하며 버티세요.', lv3: '(Q)\'파열\'을 적중시켜 코르키를 공중으로 띄운 뒤 딜교환을 시작하세요. 코르키가 (E)\'개틀링 건\'을 사용하여 방어력을 낮추기 전에 (W)\'흉포한 울부짖음\'으로 스킬 사용을 막는 것이 좋아요. (E)\'날카로운 가시\'를 섞어 함께 피해를 입히며 압박하세요.', lv6: '코르키의 체력이 낮아지면 (R)\'포식\'을 사용하여 킬을 노려보세요. 코르키가 (R)\'미사일 폭격\'을 사용하는 타이밍에는 무리하게 싸우지 않도록 주의해야 해요. 라인을 관리하며 정글러의 도움을 기다리세요.', item: '판금 장화와 강철심장을 선택해요. 코르키의 물리 피해를 견디고 체력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 코르키를 압박하다 체력이 낮아지면 점화를 더해 (R)\'포식\'으로 마무리하세요.' },
    '퀸': { lv1: '퀸은 (Q)\'실명 공격\'으로 시야를 좁히고 (P)\'매사냥\' 표식을 통해 강력한 견제를 해요. 1~2레벨에는 퀸의 평타 견제를 최대한 피하며 체력을 보존하고, 퀸이 다가오려 하면 (Q)\'파열\'을 사용하여 거리를 조절하세요. (Q)\'파열\'이 적중하면 퀸의 접근을 늦추며 안정적으로 라인을 관리해요.', lv3: '퀸이 (E)\'공중제비\'로 돌진하며 대상을 밀어내려 할 때 (Q)\'파열\'을 사용하여 퀸을 공중으로 띄우면 흐름을 끊을 수 있어요. (W)\'흉포한 울부짖음\'으로 퀸을 침묵시키면 퀸이 (E)\'공중제비\'를 쓰기 전에 스킬 사용을 막을 수 있어요. (E)\'날카로운 가시\'를 묻히며 퀸의 스킬이 빠진 빈틈을 노려 딜교환을 시도하세요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 이동하면 라인을 빠르게 밀어 포탑 압박을 가하거나 정글러를 부르세요. 퀸의 체력이 낮을 때 (R)\'포식\'을 사용하여 확실하게 처치하고 성장을 이어가야 해요. 퀸이 (E)\'공중제비\'로 거리를 벌린 뒤 (R)\'후방 지원\'으로 도망치려 할 수 있으니 주의하며 킬각을 보세요.', item: '퀸의 물리 피해를 줄이기 위해 판금 장화가 좋아요. 첫 코어 아이템으로는 라인 유지력과 지속 피해를 위해 태양불꽃 방패를 가세요.', spell: '점멸과 점화를 추천해요. (R)\'포식\'으로 퀸의 체력을 깎으며 확실하게 마무리하기 좋아요.' },
    '크산테': { lv1: '크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 접근하면 (Q)\'파열\'을 발밑에 사용해 공중으로 띄우고 거리를 벌리세요. (Q)\'엔토포 타격\'의 두 번째 중첩인 충격파에 끌려가지 않도록 주의하며 짧게 딜교환하세요. 1~2레벨 구간에는 무리하게 붙기보다 거리 조절에 집중하며 체력을 유지해요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전하는 동안은 저지 불가라 (Q)\'파열\'이나 침묵으로 돌진을 끊을 수 없으니 돌진 방향에서 비켜서세요. 다른 스킬은 쓰기 전에 (W)\'흉포한 울부짖음\'을 맞혀 막으세요. (E)\'발놀림\'으로 빠르게 진입한 상대에게는 (E)\'날카로운 가시\' 평타로 둔화를 걸고 천천히 물러나세요.', lv6: '크산테가 (R)\'총공세\'를 사용해 벽 너머로 밀어내면 상대 정글러의 개입이 쉬우니 벽 근처에서는 주의하세요. (R)\'총공세\' 상태의 크산테는 피해량이 매우 높으니 정면 승부는 피하고 (Q)\'파열\'로 접근을 계속 차단하세요. 상대의 체력이 낮아졌을 때 (R)\'포식\'으로 마무리하며 최대 체력을 쌓는 것이 중요해요.', item: '강철심장을 첫 코어로 선택해 최대 체력을 높이고 성장 잠재력을 키우세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 크산테와의 교전은 호흡이 길어지므로 순간이동으로 라인 복귀와 운영에 집중하세요.' },
    '클레드': { lv1: '1~2레벨 구간에는 클레드가 (Q)\'덫날리기\'로 붙잡아 끌어당기며 강하게 압박해요. (Q)\'파열\'을 클레드의 진입 경로에 미리 사용하여 거리 조절을 하고, 덫에 맞았다면 최대한 빠르게 클레드에게서 멀어져야 해요. 스칼이 있는 동안은 체력이 많으니 무리하게 붙지 마세요.', lv3: '(E)\'이랴!\'로 돌진하는 클레드가 붙었을 때 (W)\'흉포한 울부짖음\'으로 침묵시켜 후속 스킬 사용을 막으세요. (W)\'버럭버럭\'이 켜진 상태에서 평타 교환을 하면 빠르게 체력이 깎이니 주의해야 해요. (E)\'날카로운 가시\'와 (Q)\'파열\'을 연계해 클레드의 이동 속도를 늦추며 딜교환하세요.', lv6: '(R)\'돌겨어어억!!!\'으로 돌진하는 클레드는 보호막을 가지고 오므로 무리하게 맞붙지 말고 정글러를 기다리세요. 클레드가 스칼에서 내린 상태라면 챔피언 피해량이 줄어드니 (R)\'포식\'으로 확실하게 마무리하며 성장하세요. 라인을 당겨서 스칼이 없는 클레드를 빠르게 처치하는 구도를 만드세요.', item: '태양불꽃 방패를 가서 체력과 방어력을 챙기고 근접전에서 지속 피해를 입히세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력을 높여 클레드가 스칼을 다시 타기 전까지 버티는 것이 중요해요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 처음 맞는 유닛에 피해를 주니 미니언 뒤에 서서 막으세요. (P)\'절대 미각\' 중첩이 세 번 쌓인 상태에서 (Q)\'혀 채찍\'에 맞으면 기절하니 평타를 오래 맞으며 붙어 있지 마세요. (Q)\'파열\'을 사용해 상대의 진입을 늦추며 거리 조절을 하세요.', lv3: '(W)\'심연 잠수\'의 범위 표시가 보이면 즉시 벗어나 공중에 뜨지 않게 주의하세요. (W)\'흉포한 울부짖음\'으로 상대 스킬 사용을 막은 뒤 (E)\'날카로운 가시\'를 섞어 체력 비례 피해를 입히세요. (E)\'두꺼운 피부\'를 보호막으로 바꾸면 피해가 흡수되니 보호막이 사라진 뒤에 딜교환을 하세요.', lv6: '(R)\'포식\'의 고정 피해로 체력이 낮은 탐 켄치를 마무리하고 성장하세요. (P)\'절대 미각\' 중첩이 쌓인 상태에서 (R)\'집어삼키기\'에 먹히면 큰 피해를 입으니 주의하세요. (Q)\'파열\'로 적을 띄워 상대의 진입을 끊고 정글러와 함께 킬각을 보세요.', item: '강철심장과 헤르메스의 발걸음을 추천해요. 강철심장으로 최대 체력을 높여 성장하고, 헤르메스의 발걸음으로 탐 켄치의 군중 제어 지속시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (E)\'두꺼운 피부\'를 통한 체력 회복을 방해하세요.' },
    '트런들': { lv1: '1~2레벨 구간에는 (Q)\'깨물기\'로 공격력을 훔쳐가는 트런들이 평타 교환에서 매우 강해요. (Q)\'파열\'을 사용하여 거리를 유지하며 적절히 견제하고, 트런들이 (P)\'헌납\'으로 체력을 회복하기 쉬운 미니언 근처에서의 정면 승부는 피하세요. 무리하게 붙기보다는 거리 조절에 집중하며 체력을 보존하세요.', lv3: '(W)\'얼음 왕국\' 위에서는 트런들의 공격 속도와 이동 속도가 오르니 영역 밖으로 빠르게 벗어나세요. (E)\'얼음 기둥\'이 빠진 것을 확인한 뒤 (W)\'흉포한 울부짖음\'으로 침묵시켜 트런들의 스킬 사용을 막고 (E)\'날카로운 가시\'로 피해를 입히세요. 상대의 (Q)\'깨물기\' 쿨타임 동안 짧게 딜교환을 하고 빠지는 것이 좋아요.', lv6: '(R)\'진압\'은 내 방어력과 체력을 훔쳐가므로, 이 스킬이 사용되면 즉시 교전을 멈추고 뒤로 물러나세요. 트런들의 (R)\'진압\' 지속 시간이 끝난 뒤에 체력이 낮은 상대를 (R)\'포식\'으로 마무리하여 성장을 노리세요. (E)\'얼음 기둥\'으로 이동 경로가 막히면 정글 개입에 취약해지니 벽 근처에 서 있지 마세요.', item: '가시 갑옷과 판금 장화를 추천해요. 가시 갑옷의 치유 감소 효과로 (P)\'헌납\'과 (W)\'얼음 왕국\'의 회복량을 줄이고, 판금 장화로 (Q)\'깨물기\'를 포함한 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과가 트런들의 (P)\'헌납\'과 (W)\'얼음 왕국\' 회복력을 억제하는 데 매우 유용해요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 분노를 쌓아 치명타를 노리니 무리한 평타 교환은 피하세요. 첫 웨이브는 (Q)\'파열\'을 이용해 거리 조절을 하며 트린다미어가 무작정 들어오지 못하게 견제하세요. (Q)\'피의 갈망\'으로 체력을 회복하며 버티는 상대에게 무리하게 딜교환을 시도하지 않는 것이 중요해요.', lv3: '트린다미어가 (E)\'회전 베기\'로 진입할 때 (W)\'흉포한 울부짖음\'을 사용하여 스킬 사용을 막고 흐름을 끊으세요. 이후 (E)\'날카로운 가시\'를 섞은 평타로 둔화를 걸어 추격 거리에서 벗어나세요. 상대가 (W)\'조롱의 외침\'을 썼을 때 등을 돌려 도망치면 둔화되니, 도망치기보다 거리를 유지하며 맞서세요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 켜면 체력이 일정 이하로 내려가지 않으니 그동안은 (Q)\'파열\'과 (W)\'흉포한 울부짖음\'으로 최대한 시간을 끄세요. (R)\'불사의 분노\' 지속시간이 끝나는 타이밍에 (R)\'포식\'을 사용하여 즉시 처치하는 것이 핵심이에요. 상대가 (E)\'회전 베기\'로 갱킹을 피해 도망갈 수 있으니 아군 정글러와 미리 호흡을 맞추세요.', item: '가시 갑옷과 판금 장화를 추천해요. 판금 장화로 트린다미어의 기본 공격 피해를 줄이고 가시 갑옷으로 방어력을 높이며 상대의 체력 회복을 억제하세요.', spell: '점멸과 점화를 추천해요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 점화의 치유 감소 효과로 방해할 수 있어요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 계속해서 중독 피해를 입히고 (Q)\'실명 다트\'로 평타를 막으려 해요. (P)\'유격 전투\'로 수풀에서 갑자기 나타날 수 있으니 주의하며 거리 조절을 하세요. (Q)\'파열\'로 티모를 띄우고 둔화시키며 천천히 압박하세요.', lv3: '티모가 (Q)\'실명 다트\'를 쓰면 실명 동안 기본 공격이 빗나가니 (E)\'날카로운 가시\'를 켠 평타는 실명이 풀린 뒤에 치세요. (Q)\'파열\'로 먼저 띄운 뒤 진입하고, (W)\'흉포한 울부짖음\'을 사용해 티모가 다음 스킬을 쓰지 못하게 방해하세요. (W)\'신속한 이동\'을 쓰기 전에 침묵을 걸어 이동 속도 증가를 막으세요.', lv6: '(R)\'유독성 함정\' 버섯을 밟으면 둔화와 피해를 입으니 티모가 주로 설치하는 길목을 피해 다니세요. 티모의 체력이 낮아진 순간에 (R)\'포식\'을 사용해 고정 피해로 처치하고 체력을 성장시키세요. 티모가 버섯을 깔러 라인을 비우면 빠르게 웨이브를 밀어 포탑 압박을 하세요.', item: '헤르메스의 발걸음과 심연의 가면을 추천해요. 마법 저항력과 강인함으로 (R)\'유독성 함정\'의 둔화 시간을 줄이고, 높은 체력으로 독 피해를 견뎌야 해요.', spell: '점멸과 순간이동을 추천해요. 티모의 견제를 견디며 라인 유지력을 높이고, 순간이동으로 합류나 복귀를 빠르게 하세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 사용해 멀리서 압박하며 초반에 강한 모습을 보여요. (P)\'필멸자의 의지\'가 쌓여 강화된 창이 날아올 때는 거리를 벌리고 미니언을 먹으며 버티세요. (Q)\'파열\'을 활용해 판테온이 다가오려고 할 때 끊어주면 좋아요.', lv3: '판테온이 (W)\'방호의 도약\'으로 돌진해 기절시키면 스킬을 사용할 수 없으니 주의하세요. (E)\'방패 돌격\'을 사용 중일 때는 정면 피해가 무시되므로 정면에 스킬을 쓰지 말고 방패가 끝난 뒤에 (Q)\'파열\'을 사용하세요. 기절이 끝난 뒤에 (W)\'흉포한 울부짖음\'을 사용하여 판테온이 다시 스킬을 쓰지 못하게 하세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용하여 공중으로 높이 뛰어오르면 착지 지점을 보고 피해야 해요. 판테온의 스킬 연계가 끝난 뒤 체력이 낮은 적에게 (R)\'포식\'을 사용하여 확실하게 마무리하세요. 판테온이 궁극기로 떨어진 직후에 (Q)\'파열\'을 맞히면 다시 거리를 벌리기 쉬워요.', item: '판금 장화를 사용하여 판테온의 기본 공격 피해를 줄이세요. 강철심장을 첫 코어로 올려 최대 체력을 늘리며 성장하세요.', spell: '점멸과 점화를 추천해요. 점화로 판테온의 체력을 깎으며 킬각을 노려보세요.' },
    '피들스틱': { lv1: '(E)\'수확\'의 사거리 밖에서 미니언을 챙기며 거리를 조절하세요. (Q)\'파열\'을 적절한 위치에 사용해 접근을 막고 시야가 없는 곳에서는 (Q)\'공포\'에 걸리지 않게 주의해요.', lv3: '상대가 (W)\'풍작\'을 사용해 체력을 회복하려 하면 (Q)\'파열\'로 빠르게 끊어주세요. (W)\'흉포한 울부짖음\'으로 적의 스킬 사용을 막은 뒤 (E)\'날카로운 가시\'와 기본 공격으로 피해를 입히세요.', lv6: '(R)\'까마귀 폭풍\'의 정신 집중 소리가 들리면 (Q)\'파열\'을 사용하여 진입을 끊어주세요. 적의 체력이 낮아진 순간 (R)\'포식\'을 사용하여 확실하게 처치하고 성장을 챙기세요. 부시 속에 숨어 있는 적의 (Q)\'공포\' 습격을 조심하며 라인을 관리해요.', item: '헤르메스의 발걸음과 심연의 가면을 추천해요. 마법 저항력을 높여 피해를 줄이고 강인함으로 공포와 침묵의 지속 시간을 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. (R)\'포식\'과 함께 사용하여 적을 확실하게 마무리하고 (W)\'풍작\'의 체력 회복을 줄일 수 있어요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 돌진하며 (E)\'대가의 검술\'로 둔화와 치명타를 입히니 거리를 조절하세요. (P)\'치명적인 검무\'로 급소를 맞히면 체력을 회복하니 급소 방향을 계속 바꿔주세요. (E)\'날카로운 가시\'를 켜고 평타를 쳐서 둔화시키며 짧게 딜교환을 하세요.', lv3: '(W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내고, 이동 불가 효과를 막으면 상대를 기절시키니 피오라가 이를 켜면 (Q)\'파열\'이나 (W)\'흉포한 울부짖음\'을 쓰지 마세요. (W)\'응수\'가 빠진 것을 확인한 뒤 (Q)\'파열\'로 띄우고 (W)\'흉포한 울부짖음\'으로 침묵시켜 스킬 사용을 막으세요. (E)\'날카로운 가시\'를 활용해 상대의 진입 속도를 늦추며 대응하세요.', lv6: '(R)\'대결투\'가 시작되면 급소들이 모두 드러나니 최대한 빠르게 움직여 급소를 내주지 마세요. 피오라의 (W)\'응수\'가 없는 타이밍에 (Q)\'파열\'로 띄운 뒤 (R)\'포식\'으로 마무리하여 체력을 성장시키세요. 라인을 밀어 넣고 정글러를 불러 피오라의 높은 유지력을 끊어내세요.', item: '강철심장을 첫 코어로 가서 최대 체력을 높이고 성장 기대값을 챙기세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'와 (R)\'대결투\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '하이머딩거': { lv1: '1~2레벨에는 하이머딩거가 (Q)\'H-28 G 진화형 포탑\'을 설치해 압박하니 무리하게 진입하지 마세요. (Q)\'파열\'을 사용해 포탑 근처의 하이머딩거를 띄우거나 견제하며 체력을 관리하세요. 최대한 포탑의 사선을 피해 미니언 막타만 챙기며 버티는 게 좋아요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'에 직격당해 기절하지 않도록 주의하며 거리 조절을 하세요. 수류탄이 빠진 틈을 타 (Q)\'파열\'로 띄운 뒤 (W)\'흉포한 울부짖음\'으로 침묵시켜 상대의 추가 스킬 사용을 막으세요. 그 후 (E)\'날카로운 가시\'를 섞어 짧게 공격하고 빠르게 빠지세요.', lv6: '(R)\'업그레이드!!!\'를 사용한 강화 수류탄의 넓은 기절 범위와 피해량을 주의하세요. 상대의 주요 스킬이 빠졌을 때 (Q)\'파열\'로 진입해 (R)\'포식\'으로 한 번에 마무리하는 킬각을 보세요. 포탑이 밀집된 지역에 무리하게 들어가지 말고 정글러를 부르기 좋은 구도를 만드세요.', item: '강철심장과 헤르메스의 발걸음을 추천해요. 강철심장으로 최대 체력을 높여 포탑의 누적 피해를 견디고, 헤르메스의 발걸음으로 마법 저항력을 챙기며 기절 지속시간을 줄이세요.', spell: '점멸과 순간이동을 추천해요. 하이머딩거의 강력한 라인 푸시력으로 인한 손해를 최소화하고 빠르게 복귀해 라인전을 이어가세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_chogath);
if (typeof module !== 'undefined') module.exports = top_chogath;
